#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum Lm2Action {
    Keep,
    Marginalia,
    HideNoise,
}

impl Lm2Action {
    fn as_str(self) -> &'static str {
        match self {
            Self::Keep => "keep",
            Self::Marginalia => "marginalia",
            Self::HideNoise => "hide_noise",
        }
    }

    fn index(self) -> usize {
        match self {
            Self::Keep => 0,
            Self::Marginalia => 1,
            Self::HideNoise => 2,
        }
    }
}

