#[cfg(feature = "devtools")]
pub fn run_lm2_eval(args: impl IntoIterator<Item = OsString>) -> Result<(), String> {
    let mut examples_input = PathBuf::from(
        "training-data/layout-role-core/lawpdf-layout-role-examples-chandra-expanded-fast-20260604.json",
    );
    let mut labels_input =
        PathBuf::from("training-data/layout-role-core/lawpdf-latest-labels-v3-holdout.json");
    let mut output_path: Option<PathBuf> = None;
    let mut disagreements_output_path: Option<PathBuf> = None;
    let mut disagreements_limit = 100usize;
    let mut use_example_role_hints = false;
    let mut external_emissions_path: Option<PathBuf> = None;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--lm2-eval") {
            continue;
        }
        if arg == OsStr::new("--examples-input") {
            examples_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--examples-input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--labels") {
            labels_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--labels needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--disagreements-output") {
            disagreements_output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--disagreements-output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--disagreements-limit") {
            let value = args
                .next()
                .ok_or_else(|| "--disagreements-limit needs a value".to_owned())?;
            disagreements_limit = value
                .to_string_lossy()
                .parse::<usize>()
                .map_err(|_| "--disagreements-limit must be a non-negative integer".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--lm2-external-emissions")
            || arg == OsStr::new("--external-emissions")
        {
            external_emissions_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--lm2-external-emissions needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--use-example-role-hints") {
            use_example_role_hints = true;
            continue;
        }
        if arg.to_string_lossy().starts_with("--") {
            return Err(format!(
                "unknown LM2 eval argument: {}",
                arg.to_string_lossy()
            ));
        }
    }

    let runtime = Lm2Runtime::load(Lm2RuntimeChoice::Automatic);
    let external_emissions = external_emissions_path
        .as_deref()
        .map(Lm2ExternalEmissions::load)
        .transpose()?;
    let examples: Lm2EvalExamplesFile = read_json_file(&examples_input)?;
    let labels: Lm2EvalLabelsFile = read_json_file(&labels_input)?;
    let mut label_by_key = HashMap::new();
    for label in &labels.labels {
        label_by_key.insert(
            eval_key(&label.path, label.page_index, label.line_index, &label.text),
            label,
        );
    }

    let mut groups: BTreeMap<(String, usize), Vec<Lm2EvalItem>> = BTreeMap::new();
    let mut matched_rows = 0usize;
    for (row, mut source) in eval_sources_for_rows(examples.lines, use_example_role_hints) {
        let Some(label) = label_by_key.get(&eval_key(
            &row.path,
            row.page_index,
            row.line_index,
            &row.text,
        )) else {
            continue;
        };
        annotate_pp_prior(&runtime, &row.path, &mut source);
        matched_rows += 1;
        groups
            .entry((row.path.to_ascii_lowercase(), row.page_index))
            .or_default()
            .push(Lm2EvalItem {
                source,
                actual: action_for_role_name(&label.role),
            });
    }

    let mut confusion = [[0usize; 3]; 3];
    let mut block_quality = Lm2BlockQualityAccumulator::default();
    let mut disagreements = Vec::new();
    for ((path, page_index), mut items) in groups {
        items.sort_by_key(|item| item.source.line_index);
        let sources = items
            .iter()
            .map(|item| item.source.clone())
            .collect::<Vec<_>>();
        let external_scores = external_emissions
            .as_ref()
            .map(|external| external.page_scores(Path::new(&path), &sources))
            .transpose()?;
        let decoded = decode_page_with_emissions(&runtime, &sources, external_scores.as_deref());
        for (index, (item, (_, predicted))) in items.iter().zip(decoded.iter()).enumerate() {
            confusion[item.actual.index()][predicted.index()] += 1;
            if item.actual != *predicted {
                disagreements.push(Lm2EvalDisagreement {
                    path: path.clone(),
                    page_index,
                    line_index: item.source.line_index,
                    actual: item.actual.as_str(),
                    predicted: predicted.as_str(),
                    previous_text: index
                        .checked_sub(1)
                        .and_then(|previous| items.get(previous))
                        .map(|previous| previous.source.text.clone()),
                    text: item.source.text.clone(),
                    next_text: items.get(index + 1).map(|next| next.source.text.clone()),
                    y_bottom: item.source.bottom / item.source.page_height.max(1.0),
                    font_ratio_page: item.source.font_ratio_page,
                    font_ratio_doc: item.source.font_ratio_doc,
                    doc_footnote_state: item.source.doc_footnote_state,
                    doc_footnote_continuation: item.source.doc_footnote_continuation,
                    doc_note_marker: item.source.doc_note_marker,
                    doc_note_marker_first_on_page: item.source.doc_note_marker_first_on_page,
                    doc_note_marker_mid_sequence_page: item
                        .source
                        .doc_note_marker_mid_sequence_page,
                    doc_note_marker_follows_previous_page: item
                        .source
                        .doc_note_marker_follows_previous_page,
                    doc_note_marker_page_delta: item.source.doc_note_marker_page_delta,
                    below_footnote_divider: item.source.below_footnote_divider,
                    page_has_footnote_divider: item.source.page_has_footnote_divider,
                });
            }
        }
        block_quality.add_page(&decoded);
    }
    if let Some(path) = disagreements_output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        let mut jsonl = String::new();
        for row in disagreements.iter().take(disagreements_limit) {
            jsonl.push_str(&serde_json::to_string(row).map_err(|error| error.to_string())?);
            jsonl.push('\n');
        }
        std::fs::write(&path, jsonl).map_err(|error| error.to_string())?;
    }
    let pp_prior_source = runtime.pp_prior_source();
    let report = lm2_eval_report(
        runtime.model_label,
        pp_prior_source,
        runtime.pp_footnote_region_membership,
        external_emissions_path.as_deref(),
        &examples_input,
        &labels_input,
        confusion,
        matched_rows,
        labels.labels.len(),
        use_example_role_hints,
        block_quality.finish(),
    );
    let json = serde_json::to_string_pretty(&report).map_err(|error| error.to_string())?;
    if let Some(path) = output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        std::fs::write(&path, json).map_err(|error| error.to_string())?;
    } else {
        println!("{json}");
    }
    Ok(())
}

#[cfg(feature = "devtools")]
pub fn run_lm2_feature_dump(args: impl IntoIterator<Item = OsString>) -> Result<(), String> {
    let mut examples_input = PathBuf::from(
        "training-data/layout-role-core/lawpdf-layout-role-examples-chandra-expanded-fast-20260604.json",
    );
    let mut output_path: Option<PathBuf> = None;
    let mut limit = 20usize;
    let mut feature_dim = 32768usize;
    let mut doc_font_zscores = false;
    let mut repetition_fingerprints = false;
    let mut marker_continuity = false;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--dump-lm2-features") {
            continue;
        }
        if arg == OsStr::new("--examples-input") {
            examples_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--examples-input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--limit") {
            let value = args
                .next()
                .ok_or_else(|| "--limit needs an integer".to_owned())?;
            limit = value
                .to_string_lossy()
                .parse::<usize>()
                .map_err(|error| format!("invalid --limit: {error}"))?;
            continue;
        }
        if arg == OsStr::new("--feature-dim") {
            let value = args
                .next()
                .ok_or_else(|| "--feature-dim needs an integer".to_owned())?;
            feature_dim = value
                .to_string_lossy()
                .parse::<usize>()
                .map_err(|error| format!("invalid --feature-dim: {error}"))?;
            continue;
        }
        if arg == OsStr::new("--enable-doc-font-features") {
            doc_font_zscores = true;
            continue;
        }
        if arg == OsStr::new("--enable-repetition-features") {
            repetition_fingerprints = true;
            continue;
        }
        if arg == OsStr::new("--enable-marker-continuity-features") {
            marker_continuity = true;
            continue;
        }
        if arg.to_string_lossy().starts_with("--") {
            return Err(format!(
                "unknown LM2 feature dump argument: {}",
                arg.to_string_lossy()
            ));
        }
    }

    let examples: Lm2EvalExamplesFile = read_json_file(&examples_input)?;
    let rows = eval_sources_for_rows(examples.lines, false)
        .into_iter()
        .take(limit)
        .map(|(row, source)| Lm2FeatureDumpRow {
            path: row.path.clone(),
            page_index: row.page_index,
            line_index: row.line_index,
            text: row.text.clone(),
            features: lm2_features(
                &source,
                feature_dim,
                doc_font_zscores,
                repetition_fingerprints,
                marker_continuity,
            ),
        })
        .collect::<Vec<_>>();
    let report = Lm2FeatureDumpReport {
        examples_input: examples_input.display().to_string(),
        feature_dim,
        doc_font_zscores,
        repetition_fingerprints,
        marker_continuity,
        rows,
    };
    let json = serde_json::to_string_pretty(&report).map_err(|error| error.to_string())?;
    if let Some(path) = output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        std::fs::write(path, json).map_err(|error| error.to_string())?;
    } else {
        println!("{json}");
    }
    Ok(())
}

/// Export the exact feature matrix the native CatBoost runtime consumes, with
/// labels, so the model can be retrained outside the app.
///
/// Emits JSONL: one object per line with the action label, the 116 float
/// features in `LM2_NATIVE_CATBOOST_FLOAT_FEATURES` order, the 14 categorical
/// features in `LM2_NATIVE_CATBOOST_CAT_FEATURES` order, and the text feature.
/// Reusing the runtime's own feature builders is the point: a model trained on
/// features assembled anywhere else cannot be loaded by the runtime.
#[cfg(feature = "devtools")]
pub fn run_lm2_training_export(args: impl IntoIterator<Item = OsString>) -> Result<(), String> {
    let mut examples_input = PathBuf::from(
        "training-data/layout-role-core/lawpdf-layout-role-examples-chandra-expanded-fast-20260604.json",
    );
    let mut output_path: Option<PathBuf> = None;
    let mut limit = usize::MAX;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--dump-lm2-training") {
            continue;
        }
        if arg == OsStr::new("--examples-input") {
            examples_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--examples-input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--limit") {
            limit = args
                .next()
                .ok_or_else(|| "--limit needs an integer".to_owned())?
                .to_string_lossy()
                .parse::<usize>()
                .map_err(|error| format!("invalid --limit: {error}"))?;
            continue;
        }
        return Err(format!(
            "unknown LM2 training export argument: {}",
            arg.to_string_lossy()
        ));
    }

    let output_path = output_path.ok_or_else(|| "--output is required".to_owned())?;
    let examples: Lm2EvalExamplesFile = read_json_file(&examples_input)?;
    let entries = eval_sources_for_rows(examples.lines, false);

    use std::io::Write as _;
    if let Some(parent) = output_path.parent() {
        std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
    }
    let file = std::fs::File::create(&output_path).map_err(|error| error.to_string())?;
    let mut writer = std::io::BufWriter::new(file);

    let mut written = 0usize;
    let mut skipped_unlabelled = 0usize;
    for (row, source) in entries.into_iter().take(limit) {
        let Some(role) = row.role.as_deref() else {
            skipped_unlabelled += 1;
            continue;
        };
        let Some(action) = lm2_training_action_for_role_name(role) else {
            skipped_unlabelled += 1;
            continue;
        };
        let feature_map = lm2_numeric_catboost_features(&source);
        let floats = LM2_NATIVE_CATBOOST_FLOAT_FEATURES
            .iter()
            .map(|name| feature_map.get(*name).copied().unwrap_or(0.0))
            .collect::<Vec<_>>();
        let cats = lm2_native_catboost_cat_features(&source);
        let text = collapse_whitespace(&source.text)
            .chars()
            .take(500)
            .collect::<String>();
        let record = Lm2TrainingRow {
            y: action.as_str(),
            role,
            doc: row.path.as_str(),
            page_index: row.page_index,
            line_index: row.line_index,
            f: floats,
            c: cats,
            t: text,
        };
        let json = serde_json::to_string(&record).map_err(|error| error.to_string())?;
        writeln!(writer, "{json}").map_err(|error| error.to_string())?;
        written += 1;
    }
    writer.flush().map_err(|error| error.to_string())?;
    println!(
        "wrote {written} row(s) to {} ({skipped_unlabelled} unlabelled skipped); {} float + {} cat + 1 text feature(s)",
        output_path.display(),
        LM2_NATIVE_CATBOOST_FLOAT_FEATURES.len(),
        LM2_NATIVE_CATBOOST_CAT_FEATURES.len()
    );
    Ok(())
}

/// Map an example's role name onto the runtime action space. Mirrors
/// [`lm2_context_action_for_role`] but works from the serialized role strings
/// used by the training corpora.
#[cfg(feature = "devtools")]
fn lm2_training_action_for_role_name(role: &str) -> Option<Lm2Action> {
    match role.trim().to_ascii_lowercase().as_str() {
        "footnote" | "marginalia" => Some(Lm2Action::Marginalia),
        "table" | "caption" | "contents" | "header" | "footer" | "header_footer" | "metadata"
        | "section_break" | "noise" => Some(Lm2Action::HideNoise),
        "body" | "heading" | "subheading" | "title" | "author_info" | "list_item" | "syllabus"
        | "issue" | "key_clause" | "quote" => Some(Lm2Action::Keep),
        _ => None,
    }
}

#[cfg(feature = "devtools")]
#[derive(Debug, Serialize)]
struct Lm2TrainingRow<'a> {
    y: &'a str,
    role: &'a str,
    doc: &'a str,
    page_index: usize,
    line_index: usize,
    f: Vec<f64>,
    c: Vec<String>,
    t: String,
}

#[cfg(feature = "devtools")]
pub fn run_lm2_decoder_lattice_dump(
    args: impl IntoIterator<Item = OsString>,
) -> Result<(), String> {
    let mut examples_input = PathBuf::from(
        "training-data/layout-role-core/lawpdf-layout-role-examples-chandra-expanded-fast-20260604.json",
    );
    let mut labels_input =
        PathBuf::from("training-data/layout-role-core/lawpdf-latest-labels-v3-holdout.json");
    let mut output_path: Option<PathBuf> = None;
    let mut use_example_role_hints = false;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--dump-lm2-decoder-lattice") {
            continue;
        }
        if arg == OsStr::new("--examples-input") {
            examples_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--examples-input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--labels") {
            labels_input = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--labels needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--use-example-role-hints") {
            use_example_role_hints = true;
            continue;
        }
        if arg.to_string_lossy().starts_with("--") {
            return Err(format!(
                "unknown LM2 decoder lattice dump argument: {}",
                arg.to_string_lossy()
            ));
        }
    }

    let runtime = Lm2Runtime::load(Lm2RuntimeChoice::Automatic);
    let examples: Lm2EvalExamplesFile = read_json_file(&examples_input)?;
    let labels: Lm2EvalLabelsFile = read_json_file(&labels_input)?;
    let mut label_by_key = HashMap::new();
    for label in &labels.labels {
        label_by_key.insert(
            eval_key(&label.path, label.page_index, label.line_index, &label.text),
            label,
        );
    }

    let mut groups: BTreeMap<(String, usize), Vec<Lm2EvalItem>> = BTreeMap::new();
    let mut matched_rows = 0usize;
    for (row, source) in eval_sources_for_rows(examples.lines, use_example_role_hints) {
        let Some(label) = label_by_key.get(&eval_key(
            &row.path,
            row.page_index,
            row.line_index,
            &row.text,
        )) else {
            continue;
        };
        matched_rows += 1;
        groups
            .entry((row.path.to_ascii_lowercase(), row.page_index))
            .or_default()
            .push(Lm2EvalItem {
                source,
                actual: action_for_role_name(&label.role),
            });
    }

    let mut pages = Vec::new();
    let mut line_count = 0usize;
    for ((path, page_index), mut items) in groups {
        items.sort_by_key(|item| item.source.line_index);
        let mut lines = Vec::with_capacity(items.len());
        for (index, item) in items.iter().enumerate() {
            let source = &item.source;
            let previous = index
                .checked_sub(1)
                .and_then(|previous| items.get(previous));
            lines.push(Lm2DecoderLatticeLine {
                line_index: source.line_index,
                text: source.text.clone(),
                gold_action: item.actual.as_str(),
                role_hint: source.role_hint.map(LiquidBlockRole::prompt_name),
                emission_scores_after_priors: action_scores_map(runtime.emission_scores(source)),
                start_features: start_feature_map(source),
                start_scores: start_scores_map(source.role_hint, runtime.start_score_scale),
                transition_features_from_previous: previous
                    .map(|previous| transition_feature_map(&previous.source, source)),
                transition_scores_from_previous: previous.map(|previous| {
                    transition_scores_map(&previous.source, source, runtime.transition_score_scale)
                }),
                y_bottom_ratio: source.bottom / source.page_height.max(1.0),
                font_ratio_page: source.font_ratio_page,
                font_ratio_doc: source.font_ratio_doc,
                doc_footnote_state: source.doc_footnote_state,
                doc_footnote_continuation: source.doc_footnote_continuation,
                doc_note_marker: source.doc_note_marker,
                doc_note_marker_first_on_page: source.doc_note_marker_first_on_page,
                doc_note_marker_mid_sequence_page: source.doc_note_marker_mid_sequence_page,
                doc_note_marker_follows_previous_page: source.doc_note_marker_follows_previous_page,
                doc_note_marker_page_delta: source.doc_note_marker_page_delta,
                below_footnote_divider: source.below_footnote_divider,
                page_has_footnote_divider: source.page_has_footnote_divider,
            });
        }
        line_count += lines.len();
        pages.push(Lm2DecoderLatticePage {
            path,
            page_index,
            lines,
        });
    }

    let report = Lm2DecoderLatticeReport {
        schema_version: "lm2-decoder-lattice-v1",
        model_label: runtime.model_label,
        examples_input: examples_input.display().to_string(),
        labels_input: labels_input.display().to_string(),
        matched_rows,
        label_rows: labels.labels.len(),
        page_count: pages.len(),
        line_count,
        use_example_role_hints,
        pages,
    };
    let json = serde_json::to_string_pretty(&report).map_err(|error| error.to_string())?;
    if let Some(path) = output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        std::fs::write(path, json).map_err(|error| error.to_string())?;
    } else {
        println!("{json}");
    }
    Ok(())
}

#[cfg(feature = "devtools")]
pub fn run_lm2_draft(args: impl IntoIterator<Item = OsString>) -> Result<(), String> {
    let mut input_path = PathBuf::from("eval/benchmark-v2/extracted-lines-lm2-source.json");
    let mut output_path: Option<PathBuf> = None;
    let mut apply_runtime_context = false;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--lm2-draft") {
            continue;
        }
        if arg == OsStr::new("--input") {
            input_path = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--apply-runtime-context") {
            apply_runtime_context = true;
            continue;
        }
        if arg.to_string_lossy().starts_with("--") {
            return Err(format!(
                "unknown LM2 draft argument: {}",
                arg.to_string_lossy()
            ));
        }
    }

    reject_label_like_path(&input_path)?;
    let runtime = Lm2Runtime::load(Lm2RuntimeChoice::Automatic);
    let runtime_context_layers = apply_runtime_context
        .then(|| {
            [
                runtime.context_twopass_model.as_ref(),
                runtime.context_arbiter_model.as_ref(),
            ]
            .into_iter()
            .flatten()
            .map(Lm2ContextTwopassModel::label)
            .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let input: Lm2DraftInput = read_json_file(&input_path)?;
    let mut rows = Vec::new();
    for document in input.documents {
        let mut lines = document.source_lines;
        lines.sort_by_key(|line| (line.page_index, line.line_index));
        annotate_pp_priors_for_lines(&runtime, &document.path, &mut lines);
        enrich_lm2_document_features(&mut lines);
        let (mut decoded, primary_emissions) = decode_pages_with_scores(&runtime, &lines);
        if apply_runtime_context {
            if let Some(model) = runtime.context_twopass_model.as_ref() {
                apply_context_twopass_model(
                    model,
                    Path::new(&document.path),
                    Some(&primary_emissions),
                    &mut decoded,
                );
            }
            if let Some(model) = runtime.context_arbiter_model.as_ref() {
                apply_context_twopass_model(
                    model,
                    Path::new(&document.path),
                    Some(&primary_emissions),
                    &mut decoded,
                );
            }
        }
        for (line, lm2_action) in decoded {
            let lm1_hint_action = line.role_hint.map(role_action).unwrap_or(Lm2Action::Keep);
            rows.push(Lm2DraftRow {
                path: document.path.clone(),
                selection_manifest_index: document.selection_manifest_index,
                selection_primary_stratum: document.selection_primary_stratum.clone(),
                selection_stratum_tags: document.selection_stratum_tags.clone(),
                line_id: line.id.clone(),
                page_index: line.page_index,
                line_index: line.line_index,
                text: line.text.clone(),
                lm2_action: lm2_action.as_str(),
                lm1_hint_action: lm1_hint_action.as_str(),
                role_hint: line.role_hint.map(LiquidBlockRole::prompt_name),
                y_bottom_ratio: line.bottom / line.page_height.max(1.0),
                font_ratio_page: line.font_ratio_page,
                font_ratio_doc: line.font_ratio_doc,
                doc_footnote_state: line.doc_footnote_state,
                doc_footnote_continuation: line.doc_footnote_continuation,
                doc_note_marker: line.doc_note_marker,
                doc_note_marker_first_on_page: line.doc_note_marker_first_on_page,
                doc_note_marker_mid_sequence_page: line.doc_note_marker_mid_sequence_page,
                doc_note_marker_follows_previous_page: line.doc_note_marker_follows_previous_page,
                doc_note_marker_page_delta: line.doc_note_marker_page_delta,
                below_footnote_divider: line.below_footnote_divider,
                page_has_footnote_divider: line.page_has_footnote_divider,
            });
        }
    }

    let pp_prior_source = runtime.pp_prior_source();
    let report = Lm2DraftReport {
        schema_version: "lm2-benchmark-draft-v1",
        model_label: runtime.model_label,
        applied_runtime_context: apply_runtime_context,
        runtime_context_layers,
        pp_prior_source,
        pp_footnote_region_membership: runtime.pp_footnote_region_membership,
        source_input: input_path.display().to_string(),
        document_count: rows
            .iter()
            .map(|row| row.path.as_str())
            .collect::<std::collections::BTreeSet<_>>()
            .len(),
        row_count: rows.len(),
        rows,
    };
    let json = serde_json::to_string_pretty(&report).map_err(|error| error.to_string())?;
    if let Some(path) = output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        std::fs::write(&path, json).map_err(|error| error.to_string())?;
    } else {
        println!("{json}");
    }
    Ok(())
}

#[cfg(feature = "devtools")]
pub fn run_lm2_source_smoke(args: impl IntoIterator<Item = OsString>) -> Result<(), String> {
    let mut input_path = PathBuf::from("eval/benchmark-v2/extracted-lines-lm2-source.json");
    let mut output_path: Option<PathBuf> = None;
    let mut external_emissions_path: Option<PathBuf> = None;
    let mut args = args.into_iter();

    while let Some(arg) = args.next() {
        if arg == OsStr::new("--lm2-source-smoke") {
            continue;
        }
        if arg == OsStr::new("--input") {
            input_path = args
                .next()
                .map(PathBuf::from)
                .ok_or_else(|| "--input needs a path".to_owned())?;
            continue;
        }
        if arg == OsStr::new("--output") {
            output_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--output needs a path".to_owned())?,
            );
            continue;
        }
        if arg == OsStr::new("--lm2-external-emissions")
            || arg == OsStr::new("--external-emissions")
        {
            external_emissions_path = Some(
                args.next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--lm2-external-emissions needs a path".to_owned())?,
            );
            continue;
        }
        if arg.to_string_lossy().starts_with("--") {
            return Err(format!(
                "unknown LM2 source smoke argument: {}",
                arg.to_string_lossy()
            ));
        }
    }

    let input: Lm2DraftInput = read_json_file(&input_path)?;
    let mut documents = Vec::with_capacity(input.documents.len());
    for document in input.documents {
        let source_lines = document
            .source_lines
            .iter()
            .filter(|line| !line.text.trim().is_empty())
            .cloned()
            .collect::<Vec<_>>();
        let request = LiquidMode2Request {
            document_epoch: 0,
            path: PathBuf::from(&document.path),
            title: document.path.clone(),
            pages: Vec::new(),
            deep_source_lines: source_lines.clone(),
            use_pymupdf_blocks: false,
            use_pp_footnote_regions: false,
            external_emissions_path: external_emissions_path.clone(),
            runtime_choice: Lm2RuntimeChoice::Automatic,
            preview_only: false,
        };
        match prepare_liquid_mode2_document(request) {
            Ok(liquid) => documents.push(Lm2SourceSmokeDocument {
                path: document.path,
                source_lines,
                block_source_lines: liquid.block_source_lines,
                error: None,
            }),
            Err(error) => documents.push(Lm2SourceSmokeDocument {
                path: document.path,
                source_lines,
                block_source_lines: Vec::new(),
                error: Some(error),
            }),
        }
    }
    let failures = documents
        .iter()
        .filter(|document| document.error.is_some())
        .count();
    let report = Lm2SourceSmokeReport {
        app_version: env!("CARGO_PKG_VERSION"),
        timestamp_unix_secs: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs(),
        document_count: documents.len(),
        failures,
        documents,
    };
    let json = serde_json::to_string_pretty(&report).map_err(|error| error.to_string())?;
    if let Some(path) = output_path {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        std::fs::write(path, json).map_err(|error| error.to_string())?;
    } else {
        println!("{json}");
    }
    Ok(())
}

pub fn prepare_liquid_mode2_document(
    request: LiquidMode2Request,
) -> Result<LiquidDocument, String> {
    prepare_liquid_mode2_document_with_timing(request).map(|(document, _)| document)
}

pub fn prepare_liquid_mode2_document_with_timing(
    request: LiquidMode2Request,
) -> Result<(LiquidDocument, LiquidMode2Timing), String> {
    let total_started = Instant::now();
    let runtime_started = Instant::now();
    let mut runtime_lease = Lm2RuntimeLease::acquire(request.runtime_choice);
    let runtime = runtime_lease.runtime();
    let mut pp_runtime_warnings = Vec::new();
    let mut liquidvision_runtime_warnings = Vec::new();
    if request.use_pp_footnote_regions {
        runtime.pp_footnote_region_membership = true;
        if runtime.pp_priors.is_none() {
            match load_or_generate_lm2_pp_priors(&request.path, &request.deep_source_lines) {
                Ok(Some(index)) => {
                    runtime.pp_priors = Some(index);
                }
                Ok(None) => {
                    runtime.pp_footnote_region_membership = false;
                    pp_runtime_warnings
                        .push("PP-DocLayout runtime produced no usable LM2 prior rows.".to_owned());
                }
                Err(error) => {
                    runtime.pp_footnote_region_membership = false;
                    pp_runtime_warnings.push(format!(
                        "PP-DocLayout runtime unavailable; using base LM2 model: {error}"
                    ));
                }
            }
        }
        if runtime.pp_footnote_region_membership
            && !runtime
                .pp_priors
                .as_ref()
                .is_some_and(lm2_pp_prior_index_has_footnotes)
        {
            runtime.pp_footnote_region_membership = false;
            if runtime.pp_priors.is_some() {
                pp_runtime_warnings.push(
                    "PP-DocLayout runtime produced no high-confidence footnote rows for LM2."
                        .to_owned(),
                );
            }
        }
    }
    let mut timing = LiquidMode2Timing {
        runtime_load_ms: runtime_started.elapsed().as_secs_f64() * 1000.0,
        ..Default::default()
    };
    let native_line_model_no_stack = runtime.native_line_model_active();
    let d1_runtime_zerospend_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_zerospend_overlay_enabled();
    let d1_runtime_continuation_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_continuation_overlay_enabled();
    let d1_runtime_immediate_continuation_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_immediate_continuation_overlay_enabled();
    let d1_runtime_sandwiched_continuation_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_sandwiched_continuation_overlay_enabled();
    let d1_runtime_wide_sandwich_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_wide_sandwich_overlay_enabled();
    let d1_runtime_safe_numeric_note_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_safe_numeric_note_overlay_enabled();
    let d1_runtime_post_wide_cue_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_post_wide_cue_overlay_enabled();
    let d1_runtime_postcue_citation_next1_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_postcue_citation_next1_overlay_enabled();
    let d1_runtime_near8_cue_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_near8_cue_overlay_enabled();
    let d1_runtime_wide_divider_guard_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_wide_divider_guard_overlay_enabled();
    let d1_runtime_geometric_zone_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_geometric_zone_overlay_enabled();
    let d1_runtime_footer_artifact_overlay =
        !native_line_model_no_stack && lm2_d1_runtime_footer_artifact_overlay_enabled();
    let footnote_monotone_overlay =
        !native_line_model_no_stack && lm2_footnote_monotone_overlay_enabled();
    let footnote_carryover_overlay =
        !native_line_model_no_stack && lm2_footnote_carryover_overlay_enabled();
    let open_footnote_carryover_overlay = lm2_open_footnote_carryover_overlay_enabled();
    let table_figure_router_overlay =
        !native_line_model_no_stack && lm2_table_figure_router_overlay_enabled();
    let page_object_overlay = !native_line_model_no_stack && lm2_page_object_overlay_enabled();
    let page_object_tuned_overlay =
        !native_line_model_no_stack && lm2_page_object_tuned_overlay_enabled();
    let d1_runtime_zerospend_overlay_version =
        d1_runtime_zerospend_overlay.then_some(LM2_D1_RUNTIME_ZEROSPEND_OVERLAY_VERSION);
    let context_twopass_label = if request.external_emissions_path.is_none() {
        let mut labels = [
            runtime.context_twopass_model.as_ref(),
            runtime.context_arbiter_model.as_ref(),
        ]
        .into_iter()
        .flatten()
        .map(Lm2ContextTwopassModel::label)
        .collect::<Vec<_>>();
        if let Some(model) = runtime.note_head_model.as_ref() {
            labels.push(model.label());
        }
        if let Some(model) = runtime.link_ranker_model.as_ref() {
            labels.push(model.label());
        }
        (!labels.is_empty()).then(|| labels.join(" -> "))
    } else {
        None
    };
    let source_signature = lm2_source_signature(
        &request.path,
        &request.pages,
        &runtime.model_label,
        context_twopass_label.as_deref(),
        runtime.pp_prior_source().as_deref(),
        runtime
            .static_front_overlay
            .as_ref()
            .map(|overlay| overlay.source_label.as_str()),
        request.use_pymupdf_blocks,
        runtime.pp_footnote_region_membership,
        runtime.marker_decoder_prior,
        runtime.small_font_decoder_prior,
        runtime.small_font_sequence_prior,
        runtime.anchored_marginalia_flow_guard,
        runtime.body_preservation_guard,
        runtime.action_neutral_blocksplit,
        runtime.toc_overlay,
        runtime.front_matter_guard,
        runtime.marginalia_preservation_guard,
        d1_runtime_zerospend_overlay,
        d1_runtime_zerospend_overlay_version,
        d1_runtime_continuation_overlay,
        d1_runtime_immediate_continuation_overlay,
        d1_runtime_sandwiched_continuation_overlay,
        d1_runtime_wide_sandwich_overlay,
        d1_runtime_safe_numeric_note_overlay,
        d1_runtime_post_wide_cue_overlay,
        d1_runtime_postcue_citation_next1_overlay,
        d1_runtime_near8_cue_overlay,
        d1_runtime_wide_divider_guard_overlay,
        d1_runtime_geometric_zone_overlay,
        d1_runtime_footer_artifact_overlay,
        footnote_monotone_overlay,
        footnote_carryover_overlay,
        table_figure_router_overlay,
        page_object_overlay,
        page_object_tuned_overlay,
        runtime.start_score_scale,
        runtime.transition_score_scale,
    );
    let external_emissions = request
        .external_emissions_path
        .as_deref()
        .map(Lm2ExternalEmissions::load)
        .transpose()?;
    if external_emissions.is_none()
        && !open_footnote_carryover_overlay
        && let Some(cached) = load_cached_lm2_document(&source_signature)
    {
        if !cached.blocks.is_empty() && !cached.block_source_lines.is_empty() {
            timing.cache_hit = true;
            timing.total_ms = total_started.elapsed().as_secs_f64() * 1000.0;
            return Ok((cached, timing));
        }
    }

    let feature_started = Instant::now();
    let mut lines = request
        .deep_source_lines
        .iter()
        .filter(|line| !line.text.trim().is_empty())
        .cloned()
        .collect::<Vec<_>>();
    if native_line_model_no_stack
        && liquidvision_enabled(true)
        && !lines.iter().all(|line| line.lv.has_region)
    {
        match PdfEngine::new()
            .map_err(|error| error.to_string())
            .and_then(|engine| {
                fill_document_features(&engine, &request.path, request.pages.len(), &mut lines)
                    .map_err(|error| error.to_string())
            }) {
            Ok(report) => {
                timing.liquidvision_fill_ms = report.elapsed_ms;
                if report.pages_filled != report.pages_attempted || !report.errors.is_empty() {
                    liquidvision_runtime_warnings.push(format!(
                        "LiquidVision populated {}/{} pages; {} page error(s): {}",
                        report.pages_filled,
                        report.pages_attempted,
                        report.errors.len(),
                        report.errors.join("; ")
                    ));
                }
            }
            Err(error) => liquidvision_runtime_warnings.push(format!(
                "LiquidVision runtime feature fill failed; native model received zero vision features: {error}"
            )),
        }
    } else if native_line_model_no_stack && !liquidvision_enabled(true) {
        liquidvision_runtime_warnings.push(
            "LiquidVision was disabled; native model received zero vision features.".to_owned(),
        );
    }
    annotate_pp_priors_for_lines(&runtime, &request.path.display().to_string(), &mut lines);
    enrich_lm2_document_features(&mut lines);
    timing.feature_enrichment_ms =
        (feature_started.elapsed().as_secs_f64() * 1000.0 - timing.liquidvision_fill_ms).max(0.0);
    if lines.is_empty() {
        let document = LiquidDocument {
            title: request.title,
            blocks: Vec::new(),
            article_spans: Vec::new(),
            block_source_lines: Vec::new(),
            footnote_links: Vec::new(),
            footnote_link_integrity: None,
            profile: Some(lm2_profile()),
            noise_lines_removed: 0,
            llm_used: false,
            llm_provider: Some("LM2".to_owned()),
            deep_liquid_used: false,
            deep_liquid_model: Some(runtime.model_label.clone()),
            warnings: vec![
                "LiquidMode2 found no selectable text. Run OCR before using LM2.".to_owned(),
            ],
            source_signature,
        };
        if external_emissions.is_none() && !open_footnote_carryover_overlay {
            let _ = save_cached_lm2_document(&document);
        }
        timing.total_ms = total_started.elapsed().as_secs_f64() * 1000.0;
        return Ok((document, timing));
    }

    let model_started = Instant::now();
    let (mut decoded, primary_emissions) = if let Some(external) = external_emissions.as_ref() {
        (
            decode_pages_with_external_emissions(&runtime, &request.path, &lines, external)?,
            None,
        )
    } else {
        let (decoded, emissions) = decode_pages_with_scores(&runtime, &lines);
        (decoded, Some(emissions))
    };
    timing.model_decode_ms = model_started.elapsed().as_secs_f64() * 1000.0;

    let overlay_started = Instant::now();
    if external_emissions.is_none()
        && let Some(model) = runtime.context_twopass_model.as_ref()
    {
        apply_context_twopass_model(
            model,
            &request.path,
            primary_emissions.as_deref(),
            &mut decoded,
        );
    }
    if external_emissions.is_none()
        && let Some(model) = runtime.context_arbiter_model.as_ref()
    {
        apply_context_twopass_model(
            model,
            &request.path,
            primary_emissions.as_deref(),
            &mut decoded,
        );
    }
    if let Some(overlay) = runtime.static_front_overlay.as_ref() {
        apply_static_front_overlay(overlay, &request.path, &mut decoded);
    }
    if runtime.toc_overlay {
        apply_document_toc_overlay(&mut decoded);
    }
    if runtime.front_matter_guard {
        apply_front_matter_guard(&mut decoded);
    }
    if runtime.marginalia_preservation_guard {
        apply_marginalia_preservation_guard(&mut decoded);
    }
    if d1_runtime_zerospend_overlay {
        apply_d1_runtime_zerospend_overlay(&mut decoded);
    }
    if d1_runtime_continuation_overlay {
        apply_d1_runtime_continuation_overlay(&mut decoded);
    }
    if d1_runtime_immediate_continuation_overlay {
        apply_d1_runtime_immediate_continuation_overlay(&mut decoded);
    }
    if d1_runtime_sandwiched_continuation_overlay {
        apply_d1_runtime_sandwiched_continuation_overlay(&mut decoded);
    }
    if d1_runtime_wide_sandwich_overlay {
        apply_d1_runtime_wide_sandwich_overlay(&mut decoded);
    }
    if d1_runtime_safe_numeric_note_overlay {
        apply_d1_runtime_safe_numeric_note_overlay(&mut decoded);
    }
    if d1_runtime_post_wide_cue_overlay {
        apply_d1_runtime_post_wide_cue_overlay(&mut decoded);
    }
    if d1_runtime_postcue_citation_next1_overlay {
        apply_d1_runtime_postcue_citation_next1_overlay(&mut decoded);
    }
    if d1_runtime_near8_cue_overlay {
        apply_d1_runtime_near8_cue_overlay(&mut decoded);
    }
    if d1_runtime_wide_divider_guard_overlay {
        apply_d1_runtime_wide_divider_guard_overlay(&mut decoded);
    }
    if table_figure_router_overlay {
        apply_table_figure_router_overlay(&mut decoded);
    }
    if page_object_overlay {
        apply_page_object_overlay(&mut decoded);
    }
    if page_object_tuned_overlay {
        apply_page_object_tuned_overlay(&mut decoded);
    }
    if d1_runtime_geometric_zone_overlay {
        apply_d1_runtime_geometric_zone_overlay(&mut decoded);
    }
    if d1_runtime_footer_artifact_overlay {
        apply_d1_runtime_footer_artifact_overlay(&mut decoded);
    }
    if footnote_carryover_overlay {
        apply_footnote_carryover_overlay(&mut decoded);
    }
    if footnote_monotone_overlay {
        // Applied after article spans are known so bound volumes do not share
        // one file-wide missing-marker chain.
    }
    if open_footnote_carryover_overlay {
        apply_open_footnote_carryover_overlay(&mut decoded);
    }
    if !native_line_model_no_stack {
        apply_page_label_furniture_guard(&mut decoded);
    }
    apply_synthetic_ocr_body_preservation(&mut decoded);
    apply_front_matter_abstract_recovery(&mut decoded);
    apply_drop_cap_recovery_overlay(&mut decoded);
    apply_same_row_body_fragment_overlay(&mut decoded);
    apply_same_page_body_callout_overlay(&mut decoded);
    if let (Some(link_model), Some(auth_model)) = (
        runtime.link_ranker_model.as_ref(),
        runtime.note_head_model.as_ref(),
    ) {
        let linker_started = Instant::now();
        apply_footnote_link_ranker(
            link_model,
            auth_model,
            &request.path,
            primary_emissions.as_deref(),
            &mut decoded,
        );
        timing.footnote_linker_ms = linker_started.elapsed().as_secs_f64() * 1000.0;
    } else if let Some(model) = runtime.note_head_model.as_ref() {
        apply_note_head_model(
            model,
            &request.path,
            primary_emissions.as_deref(),
            &mut decoded,
        );
    }
    apply_hidden_numbered_note_head_recovery(&mut decoded);
    apply_explicit_endnote_section_guard(&mut decoded);
    apply_preceding_small_font_note_continuation_guard(&mut decoded);
    // The note-head model resolves definitions that were still ambiguous when
    // the early body overlay ran. Re-run the guarded page sequence now so
    // flattened multi-digit callouts can use those newly established heads
    // before block assembly's more permissive one-digit recovery.
    apply_scanned_glyph_note_sequence_bridge(&request.path, &mut decoded);
    apply_decoded_page_sequence_callout_recovery(&mut decoded);
    apply_repository_cover_guard(&mut decoded);
    apply_strict_no_dot_toc_page_guard(&mut decoded);
    apply_dense_dotleader_toc_run_guard(&mut decoded);
    apply_final_assembly_safety_guards(&mut decoded);
    apply_isolated_body_noise_tail_recovery(&mut decoded);
    apply_numbered_table_figure_band_role_hints(&mut decoded);
    // The final furniture guard can still inherit a stale Noise hint for a
    // terse `N. Id.` line. Reassert the narrower physical note-head rule after
    // every line-level overlay has finished.
    apply_hidden_numbered_note_head_recovery(&mut decoded);
    apply_same_segment_statutory_subdivision_body_rescue(&mut decoded);
    let article_spans = detect_lm2_article_spans(&decoded, request.pages.len());
    if footnote_monotone_overlay {
        apply_footnote_monotone_overlay(&mut decoded, &article_spans);
    }
    apply_document_discretionary_hyphen_repairs(&mut decoded);
    apply_document_fused_word_spacing_repairs(&mut decoded);
    timing.overlay_decode_ms = overlay_started.elapsed().as_secs_f64() * 1000.0;

    let assembly_started = Instant::now();
    let hidden_count = decoded
        .iter()
        .filter(|(_, action)| *action == Lm2Action::HideNoise)
        .count();
    let grouping = if request.use_pymupdf_blocks {
        try_apply_lm2_pymupdf_grouping(
            &request.path,
            &request.title,
            &source_signature,
            &request.deep_source_lines,
        )
        .ok()
        .flatten()
    } else {
        None
    };
    let (title, mut blocks, mut block_source_lines) =
        build_lm2_blocks_with_grouping(&request.title, &decoded, grouping.as_ref(), &article_spans);
    apply_leading_letterspaced_author_recovery(&mut blocks, &mut block_source_lines);
    apply_false_marginalia_note_head_reflow(&mut blocks, &mut block_source_lines);
    if runtime.action_neutral_blocksplit {
        apply_action_neutral_blocksplit(&mut blocks, &mut block_source_lines, &decoded);
    }
    apply_heading_outline_splits(&mut blocks, &mut block_source_lines, &decoded);
    apply_heading_continuation_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_heading_leading_source_continuation_split(&mut blocks, &mut block_source_lines, &decoded);
    apply_front_matter_abstract_author_reflow(&mut blocks, &mut block_source_lines);
    apply_front_matter_byline_abstract_split(&mut blocks, &mut block_source_lines);
    apply_hidden_numbered_note_block_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_hidden_numbered_note_block_split_recovery(&mut blocks, &mut block_source_lines, &decoded);
    // Hidden-note recovery can expose the true head immediately before a
    // citation pincite that was itself mistaken for a note number.  Re-run
    // the provenance-backed reflow now that the true head is visible.
    apply_false_marginalia_note_head_reflow(&mut blocks, &mut block_source_lines);
    apply_table_figure_block_role_routing(&mut blocks, &block_source_lines, &decoded);
    // The first pass establishes the main table cluster. A repeated header on
    // the next page can only be recognized after that cluster is visible.
    apply_table_figure_block_role_routing(&mut blocks, &block_source_lines, &decoded);
    apply_front_matter_contents_block_suppression(&mut blocks, &mut block_source_lines);
    apply_interleaved_note_continuation_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_inline_body_callout_marginalia_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_geometry_backed_leading_callout_bridge(&mut blocks, &mut block_source_lines, &decoded);
    apply_mixed_marginalia_leading_body_callout_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_contiguous_body_marginalia_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_deferred_marginalia_reflow(&mut blocks, &mut block_source_lines);
    apply_above_note_body_marginalia_rescue(&mut blocks, &block_source_lines, &decoded);
    apply_body_callout_marginalia_rescue(&mut blocks, &block_source_lines, &decoded);
    apply_physical_sequential_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_recovered_trailing_note_marker_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_local_monotone_ascii_callout_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_mixed_marginalia_leading_body_callout_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_page_sequence_ascii_callout_recovery(&mut blocks, &mut block_source_lines);
    // The page matcher establishes additional accepted heads. Feed that
    // stronger provenance back through the exact-successor fixed point, then
    // recover locally bracketed whitespace-separated body callouts.
    apply_body_backed_bare_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_physical_sequential_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_recovered_trailing_note_marker_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_local_monotone_ascii_callout_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_mixed_marginalia_leading_body_callout_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_attached_terminal_callout_recovery(&mut blocks, &block_source_lines);
    apply_in_block_standalone_callout_recovery(&mut blocks, &block_source_lines, &decoded);
    apply_same_row_leading_callout_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_numeric_footer_furniture_suppression(&mut blocks, &block_source_lines, &decoded);
    // Rescue passes can demote a source-backed outline label while fixing its
    // surrounding body flow. Reapply the provenance-gated splitter only after
    // all such role mutations are complete.
    apply_heading_outline_splits(&mut blocks, &mut block_source_lines, &decoded);
    apply_sandwiched_numbered_outline_recovery(&mut blocks, &mut block_source_lines);
    // Later body/marginalia rescue passes can conservatively demote a true
    // single-line definition that the early hidden-note pass recovered.  Make
    // provenance-backed note heads and adjacent false pincites stable at the
    // final block boundary before linking.
    apply_hidden_numbered_note_block_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_false_marginalia_note_head_reflow(&mut blocks, &mut block_source_lines);
    // Later rescue passes can be what finally settles the preceding physical
    // note as Marginalia. Re-run the provenance-backed continuation repair at
    // that stable boundary so an interleaved small-font line cannot remain in
    // body prose merely because its note target was still ambiguous earlier.
    apply_sandwiched_body_noise_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_source_gap_body_line_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_embedded_small_font_note_continuation_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    // Late source-gap and small-font repairs can settle a body-shaped quote as
    // markerless Marginalia only after the first above-note rescue ran. Give
    // that same provenance-gated rescue one final pass before note reflow.
    apply_above_note_body_marginalia_rescue(&mut blocks, &block_source_lines, &decoded);
    apply_interleaved_note_continuation_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_source_backed_paragraph_splits(&mut blocks, &mut block_source_lines, &decoded);
    // A newly exposed paragraph boundary can also reveal that the following
    // source line is a numbered note head. Re-run provenance-backed role
    // recovery so the split cannot strand that definition in body prose.
    apply_hidden_numbered_note_block_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_false_marginalia_note_head_reflow(&mut blocks, &mut block_source_lines);
    // A same-row inline callout can only use its accepted definition after the
    // late hidden-note pass has recovered that definition's provenance. Re-run
    // the idempotent bridge here so the adjacent lowercase body row is joined
    // before the final source-backed splitter.
    apply_same_row_leading_callout_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_physical_footnote_segment_guard(&mut blocks, &mut block_source_lines, &decoded);
    // The final source-backed split can likewise expose the middle of a
    // cross-page footnote segment as a standalone Paragraph. Run the guarded
    // sequential-boundary closure to a tiny fixed point at this stable block
    // boundary: the first pass can settle the adjacent markerless segment or
    // numbered target that the second pass then uses as its boundary proof.
    for _ in 0..2 {
        if apply_interleaved_note_continuation_reflow(
            &mut blocks,
            &mut block_source_lines,
            &decoded,
        ) == 0
        {
            break;
        }
    }
    // Some body-shaped displays and top-of-page note continuations only have
    // stable ownership after the final note fixed point.  Re-assert those
    // source-backed roles here, after no broad rescue pass remains.
    apply_final_displayed_body_role_rescue(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_mixed_furniture_prefix_suppression(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_physical_footnote_segment_guard(&mut blocks, &mut block_source_lines, &decoded);
    for _ in 0..2 {
        if apply_interleaved_note_continuation_reflow(
            &mut blocks,
            &mut block_source_lines,
            &decoded,
        ) == 0
        {
            break;
        }
    }
    // Nothing note-oriented runs after this point, so a rescued display cannot
    // be pulled back into a numbered definition.
    apply_final_displayed_body_role_rescue(&mut blocks, &mut block_source_lines, &decoded);
    // The native model can emit one continuation row immediately before its
    // numbered head in block order even though the source coordinates are
    // head, continuation, then the remainder of the note. Run this only after
    // the final role/split fixed point, where those three blocks are stable.
    apply_inverted_numbered_note_continuation_reflow(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_final_caption_continuation_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_noise_inline_callout_bridge(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_fused_heading_body_splits(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_body_source_order_and_coalescing(&mut blocks, &mut block_source_lines, &decoded);
    // Reassert source-backed display boundaries after the first ordering pass,
    // then run the same guarded coalescer once more. The splitter can expose a
    // wrapped body row that was not a separate block during the first pass;
    // the coalescer already treats displayed labels, font cliffs, and genuine
    // paragraph boundaries as hard stops.
    apply_final_source_backed_paragraph_splits(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_body_source_order_and_coalescing(&mut blocks, &mut block_source_lines, &decoded);
    // Keep displayed labels separated after the last flow join. The splitter
    // explicitly ignores source-proven lowercase wraps, so this pass is
    // idempotent for repaired body flow while retaining real definitions.
    apply_final_source_backed_paragraph_splits(&mut blocks, &mut block_source_lines, &decoded);
    // The last splitter can expose a source-role boundary (for example a
    // callout-bearing row tagged Heading or Marginalia) even though the exact
    // adjacent source geometry proves one lowercase body flow. Nothing after
    // this pass can split the repaired flow again.
    apply_final_body_source_order_and_coalescing(&mut blocks, &mut block_source_lines, &decoded);
    // Reassert the strongest paired note evidence only after every broad
    // role/reflow pass has finished. A local callout rewrite may expose one
    // last body join, so coalesce once and then reassert definition markers at
    // the terminal boundary where nothing can demote them again.
    apply_body_backed_bare_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_physical_sequential_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_recovered_trailing_note_marker_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_local_monotone_ascii_callout_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_mixed_marginalia_leading_body_callout_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_final_body_source_order_and_coalescing(&mut blocks, &mut block_source_lines, &decoded);
    apply_body_backed_bare_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_physical_sequential_note_head_recovery(&mut blocks, &mut block_source_lines, &decoded);
    apply_recovered_trailing_note_marker_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_attached_terminal_callout_recovery(&mut blocks, &block_source_lines);
    apply_mixed_marginalia_leading_body_callout_split(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_terminal_out_of_order_callout_fragment_reflow(&mut blocks, &block_source_lines, &decoded);
    apply_source_backed_dotted_numeric_callout_restoration(&mut blocks, &block_source_lines);
    apply_leading_callout_backfill(&mut blocks, &block_source_lines);
    apply_adjacent_duplicate_callout_suppression(&mut blocks);
    apply_sandwiched_note_url_continuation_reflow(&mut blocks, &mut block_source_lines, &decoded);
    apply_final_source_backed_figure_caption_isolation(
        &mut blocks,
        &mut block_source_lines,
        &decoded,
    );
    apply_final_body_source_order_and_coalescing(&mut blocks, &mut block_source_lines, &decoded);
    // The terminal body coalescer can finally place a low-font statutory
    // subdivision directly between its colon lead-in and numbered children.
    // Re-run the structural display rescue at this stable boundary so the
    // Markdown note assembler cannot absorb that body display into an open
    // cross-page footnote.
    apply_final_displayed_body_role_rescue(&mut blocks, &mut block_source_lines, &decoded);
    rescue_omitted_keep_source_lines(&mut blocks, &mut block_source_lines, &decoded);
    let mut warnings = if runtime.native_line_model_active() {
        vec![format!(
            "Review Mode uses {} raw no-stack emissions.",
            runtime.model_label
        )]
    } else {
        vec![format!(
            "Review Mode uses {} emissions plus page-level sequence decoder.",
            runtime.model_label
        )]
    };
    warnings.extend(runtime.load_warnings.iter().cloned());
    if lm2_v20_runtime_preset_enabled() {
        warnings.push("LM2 v20 runtime preset is enabled.".to_owned());
    }
    if lm2_v25_d1_runtime_preset_enabled() {
        warnings.push("LM2 v25 D1 zero-spend runtime preset is enabled.".to_owned());
    }
    if (runtime.start_score_scale - 1.0).abs() > f64::EPSILON
        || (runtime.transition_score_scale - 1.0).abs() > f64::EPSILON
    {
        warnings.push(format!(
            "LM2 decoder start/transition scales are {:.3}/{:.3}.",
            runtime.start_score_scale, runtime.transition_score_scale
        ));
    }
    if let Some(label) = context_twopass_label.as_deref() {
        warnings.push(format!(
            "Review Mode learned postprocessor stack is active: {label}."
        ));
    }
    if !runtime.native_line_model_active()
        && runtime.numeric_catboost_model.is_none()
        && runtime.model.is_none()
    {
        warnings.push("LM2 trained model not found; used geometry fallback emissions.".to_owned());
    }
    if let Some(external) = external_emissions.as_ref() {
        warnings.push(format!(
            "LM2 external emissions override is enabled: {}. LM2 document cache was bypassed.",
            external.source_label()
        ));
    }
    if runtime.marker_decoder_prior {
        warnings.push("EXP-061 marker-continuity decoder prior is enabled.".to_owned());
    }
    if runtime.small_font_decoder_prior {
        warnings.push("EXP-062 small-font lower-page decoder prior is enabled.".to_owned());
    }
    if runtime.anchored_marginalia_flow_guard {
        warnings.push("EXP-069 anchored marginalia flow guard is enabled.".to_owned());
    }
    if runtime.body_preservation_guard {
        warnings.push("LM2 body-preservation guard is enabled.".to_owned());
    }
    if runtime.action_neutral_blocksplit {
        warnings.push("LM2 action-neutral blocksplit is enabled.".to_owned());
    }
    if runtime.toc_overlay {
        warnings.push("LM2 document-local TOC overlay is enabled.".to_owned());
    }
    if runtime.front_matter_guard {
        warnings.push("LM2 first-page front-matter guard is enabled.".to_owned());
    }
    if runtime.marginalia_preservation_guard {
        warnings.push("LM2 marginalia-preservation guard is enabled.".to_owned());
    }
    if d1_runtime_zerospend_overlay {
        warnings.push("LM2 D1 zero-spend keep-to-marginalia overlay is enabled.".to_owned());
    }
    if d1_runtime_continuation_overlay {
        warnings.push("LM2 D1 continuation keep-to-marginalia overlay is enabled.".to_owned());
    }
    if d1_runtime_immediate_continuation_overlay {
        warnings.push(
            "LM2 D1 immediate-neighbor continuation keep-to-marginalia overlay is enabled."
                .to_owned(),
        );
    }
    if d1_runtime_sandwiched_continuation_overlay {
        warnings.push(
            "LM2 D1 sandwiched continuation keep-to-marginalia overlay is enabled.".to_owned(),
        );
    }
    if d1_runtime_wide_sandwich_overlay {
        warnings.push(
            "LM2 D1 wide sandwiched continuation keep-to-marginalia overlay is enabled.".to_owned(),
        );
    }
    if d1_runtime_safe_numeric_note_overlay {
        warnings.push(
            "LM2 D1 safe numeric note-start keep-to-marginalia overlay is enabled.".to_owned(),
        );
    }
    if d1_runtime_post_wide_cue_overlay {
        warnings.push("LM2 D1 post-wide cue keep-to-marginalia overlay is enabled.".to_owned());
    }
    if d1_runtime_postcue_citation_next1_overlay {
        warnings.push(
            "LM2 D1 postcue citation-next1 keep-to-marginalia overlay is enabled.".to_owned(),
        );
    }
    if d1_runtime_near8_cue_overlay {
        warnings.push("LM2 D1 near8 cue keep-to-marginalia overlay is enabled.".to_owned());
    }
    if d1_runtime_wide_divider_guard_overlay {
        warnings
            .push("LM2 D1 wide-divider guarded keep-to-marginalia overlay is enabled.".to_owned());
    }
    if d1_runtime_footer_artifact_overlay {
        warnings.push("LM2 D1 footer-artifact hide-noise overlay is enabled.".to_owned());
    }
    if footnote_monotone_overlay {
        warnings.push("LM2 global footnote-number monotonicity overlay is enabled.".to_owned());
    }
    if footnote_carryover_overlay {
        warnings.push("LM2 footnote carryover hard overlay is enabled.".to_owned());
    }
    if open_footnote_carryover_overlay {
        warnings.push("LM2 open-footnote carryover hard overlay is enabled.".to_owned());
    }
    if page_object_tuned_overlay {
        warnings.push("LM2 page-object tuned hide-noise overlay is enabled.".to_owned());
    }
    if let Some(overlay) = runtime.static_front_overlay.as_ref() {
        warnings.push(format!(
            "LM2 static front overlay is enabled: {}.",
            overlay.source_label
        ));
    }
    if runtime.pp_footnote_region_membership {
        warnings.push("EXP-075 PP footnote-region membership override is enabled.".to_owned());
    }
    if article_spans.len() > 1 {
        warnings.push(format!(
            "Detected {} article spans in this PDF.",
            article_spans.len()
        ));
    }
    warnings.extend(pp_runtime_warnings);
    warnings.extend(liquidvision_runtime_warnings);
    if let Some(grouping) = &grouping {
        if let Some(mode) = &grouping.mode {
            warnings.push(format!("PyMuPDF block grouping mode: {mode}"));
        }
        warnings.extend(
            grouping
                .warnings
                .iter()
                .map(|warning| format!("PyMuPDF block grouping: {warning}")),
        );
    }

    let mut document = LiquidDocument {
        title,
        blocks,
        article_spans,
        block_source_lines,
        footnote_links: Vec::new(),
        footnote_link_integrity: None,
        profile: Some(lm2_profile()),
        noise_lines_removed: hidden_count,
        llm_used: false,
        llm_provider: Some("LM2".to_owned()),
        deep_liquid_used: false,
        deep_liquid_model: Some(runtime.model_label.clone()),
        warnings,
        source_signature,
    };
    attach_footnote_links(&mut document);
    if external_emissions.is_none() && !open_footnote_carryover_overlay {
        let _ = save_cached_lm2_document(&document);
    }
    timing.assembly_ms = assembly_started.elapsed().as_secs_f64() * 1000.0;
    timing.total_ms = total_started.elapsed().as_secs_f64() * 1000.0;
    Ok((document, timing))
}

fn detect_lm2_article_spans(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    page_count: usize,
) -> Vec<crate::liquid::ArticleSpan> {
    let lines = decoded
        .iter()
        .map(|(line, action)| ArticleSegmentationLine {
            page_index: line.page_index,
            line_index: line.line_index,
            text: line.text.clone(),
            font_ratio_page: line.font_ratio_page,
            font_ratio_doc: line.font_ratio_doc,
            margin_centered: line.margin_centered,
            line_width_ratio: line.line_width_ratio,
            top: line.top,
            page_height: line.page_height,
            repeated_edge_text: line.doc_repeated_edge_text,
            toc_like: line.segment_block_toc_like,
            note_marker: note_head_marker(&line.text)
                .or((line.doc_note_marker > 0).then_some(line.doc_note_marker)),
            // Boundary evidence must not depend solely on the final emission
            // action. The old scans that most need article scoping are also
            // the documents where note lines are commonly misclassified.
            marginalia: *action == Lm2Action::Marginalia
                || line.doc_footnote_state
                || line.in_footnote_zone
                || line.below_footnote_divider
                || line.segment_block_footnote_like,
        })
        .collect::<Vec<_>>();
    let detected = detect_article_spans(&lines, page_count);
    filter_lm2_false_article_spans(detected, decoded, page_count)
}

fn filter_lm2_false_article_spans(
    detected: Vec<ArticleSpan>,
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    page_count: usize,
) -> Vec<ArticleSpan> {
    if detected.len() <= 1 {
        return detected;
    }
    let mut kept = detected
        .into_iter()
        .enumerate()
        .filter_map(|(index, span)| {
            (index == 0 || !lm2_false_article_boundary(&span, decoded)).then_some(span)
        })
        .collect::<Vec<_>>();
    for index in 0..kept.len() {
        kept[index].article_index = index;
        if let Some((next_page, next_line)) = kept
            .get(index + 1)
            .map(|next| (next.start_page_index, next.start_line_index))
        {
            kept[index].end_page_index = next_page;
            kept[index].end_line_index = next_line;
        } else {
            kept[index].end_page_index = page_count;
            kept[index].end_line_index = 0;
        }
    }
    kept
}

fn lm2_false_article_boundary(
    span: &ArticleSpan,
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
) -> bool {
    if span.start_page_index == 0 {
        return false;
    }
    let caption_band = decoded.iter().any(|(line, _)| {
        line.page_index == span.start_page_index
            && line.line_index <= 8
            && lm2_numbered_table_figure_caption(&line.text)
    });
    if caption_band {
        return true;
    }

    let typography_only_internal_outline = span.confidence <= 0.60
        && span
            .title_hint
            .as_deref()
            .is_some_and(lm2_internal_outline_title_hint)
        && !span
            .evidence
            .iter()
            .any(|item| matches!(item.kind.as_str(), "publication_section" | "footnote_reset"));
    typography_only_internal_outline
}

fn lm2_numbered_table_figure_caption(text: &str) -> bool {
    let normalized = normalize_text(text);
    let mut words = normalized.split_whitespace();
    if !matches!(words.next(), Some("table" | "figure" | "fig.")) {
        return false;
    }
    words.next().is_some_and(|token| {
        let marker = token.trim_matches(|ch: char| matches!(ch, '.' | ':' | ')' | ']'));
        !marker.is_empty()
            && marker.len() <= 8
            && (marker.chars().all(|ch| ch.is_ascii_digit())
                || marker.chars().all(|ch| {
                    matches!(
                        ch.to_ascii_lowercase(),
                        'i' | 'v' | 'x' | 'l' | 'c' | 'd' | 'm'
                    )
                }))
    })
}

fn lm2_explicit_numbered_table_figure_caption(text: &str) -> bool {
    let normalized = normalize_text(text);
    let mut words = normalized.split_whitespace();
    if !matches!(words.next(), Some("table" | "figure" | "fig.")) {
        return false;
    }
    words.next().is_some_and(|token| {
        let has_caption_punctuation = token.ends_with(':');
        let marker = token.trim_end_matches(':');
        has_caption_punctuation
            && !marker.is_empty()
            && marker.len() <= 8
            && (marker.chars().all(|ch| ch.is_ascii_digit())
                || marker.chars().all(|ch| {
                    matches!(
                        ch.to_ascii_lowercase(),
                        'i' | 'v' | 'x' | 'l' | 'c' | 'd' | 'm'
                    )
                }))
    })
}

fn lm2_internal_outline_title_hint(text: &str) -> bool {
    let token = text.split_whitespace().next().unwrap_or_default();
    if !token.ends_with('.') && !token.ends_with(')') {
        return false;
    }
    let marker = token.trim_matches(|ch: char| matches!(ch, '(' | ')' | '.'));
    !marker.is_empty()
        && marker.len() <= 8
        && marker.chars().all(|ch| {
            matches!(
                ch.to_ascii_lowercase(),
                'i' | 'v' | 'x' | 'l' | 'c' | 'd' | 'm'
            )
        })
}

pub(crate) fn trace_article_spans_from_source_lines(
    source_lines: &[DeepLiquidSourceLine],
    page_count: usize,
) -> (
    Vec<crate::liquid::ArticleSpan>,
    Vec<ArticleBoundaryCandidateTrace>,
) {
    let lines = source_lines
        .iter()
        .map(|line| ArticleSegmentationLine {
            page_index: line.page_index,
            line_index: line.line_index,
            text: line.text.clone(),
            font_ratio_page: line.font_ratio_page,
            font_ratio_doc: line.font_ratio_doc,
            margin_centered: line.margin_centered,
            line_width_ratio: line.line_width_ratio,
            top: line.top,
            page_height: line.page_height,
            repeated_edge_text: line.doc_repeated_edge_text,
            toc_like: line.segment_block_toc_like,
            note_marker: note_head_marker(&line.text)
                .or((line.doc_note_marker > 0).then_some(line.doc_note_marker)),
            marginalia: line.doc_footnote_state
                || line.in_footnote_zone
                || line.below_footnote_divider
                || line.segment_block_footnote_like,
        })
        .collect::<Vec<_>>();
    detect_article_spans_with_trace(&lines, page_count)
}

impl Lm2Runtime {
    fn load(runtime_choice: Lm2RuntimeChoice) -> Self {
        let mut load_warnings = Vec::new();
        let pp_priors = load_lm2_pp_priors().ok().flatten();
        let fasttab_requested = runtime_choice.fasttab_requested();
        let fasttab_model = match Lm2FastTabModel::load_requested(fasttab_requested) {
            Ok(Some(model)) => Some(model),
            Ok(None) => {
                if fasttab_requested {
                    load_warnings.push(
                        "Requested FastTab runtime asset was not found; retaining CatBoost default."
                            .to_owned(),
                    );
                }
                None
            }
            Err(error) => {
                load_warnings.push(format!(
                    "Requested FastTab runtime failed to load; retaining CatBoost default: {error}"
                ));
                None
            }
        };
        let native_catboost_model = match load_lm2_native_catboost_model() {
            Ok(Some(model)) => Some(model),
            Ok(None) => {
                load_warnings.push(
                    "Promoted native CatBoost runtime assets were not found; using fallback emissions."
                        .to_owned(),
                );
                None
            }
            Err(error) => {
                load_warnings.push(format!(
                    "Promoted native CatBoost runtime failed to load; using fallback emissions: {error}"
                ));
                None
            }
        };
        let native_line_model_active = fasttab_model.is_some() || native_catboost_model.is_some();
        let context_primary_sha256 = if fasttab_model.is_none() {
            native_catboost_model
                .as_ref()
                .map(|model| model.model_sha256.as_str())
        } else {
            None
        };
        let context_twopass_model = if native_line_model_active && lm2_context_twopass_enabled() {
            match load_lm2_context_twopass_model(context_primary_sha256) {
                Ok(Some(model)) => Some(model),
                Ok(None) => {
                    load_warnings.push(
                        "Promoted context two-pass model was not found; using native emissions only."
                            .to_owned(),
                    );
                    None
                }
                Err(error) => {
                    load_warnings.push(format!(
                        "Promoted context two-pass model failed to load; using native emissions only: {error}"
                    ));
                    None
                }
            }
        } else {
            None
        };
        let context_arbiter_model = if native_catboost_model.is_some()
            && fasttab_model.is_none()
            && lm2_context_twopass_enabled()
        {
            match load_lm2_context_arbiter_model(
                context_primary_sha256,
                context_twopass_model
                    .as_ref()
                    .map(|model| model.asset_sha256.as_str()),
            ) {
                Ok(model) => model,
                Err(error) => {
                    load_warnings.push(format!(
                        "Optional context arbiter failed to load; retaining the promoted context model only: {error}"
                    ));
                    None
                }
            }
        } else {
            None
        };
        let note_head_model = if native_line_model_active {
            match load_lm2_note_head_model(context_primary_sha256) {
                Ok(model) => model,
                Err(error) => {
                    load_warnings.push(format!(
                        "Optional learned note-head scorer failed to load: {error}"
                    ));
                    None
                }
            }
        } else {
            None
        };
        let link_ranker_model = if native_line_model_active {
            match load_lm2_link_ranker_model(note_head_model.as_ref()) {
                Ok(model) => model,
                Err(error) => {
                    load_warnings.push(format!(
                        "Optional learned footnote link ranker failed to load: {error}"
                    ));
                    None
                }
            }
        } else {
            None
        };
        let numeric_catboost_model = if native_line_model_active {
            None
        } else {
            load_lm2_numeric_catboost_model().ok().flatten()
        };
        let static_front_overlay = if native_line_model_active {
            None
        } else {
            load_lm2_static_front_overlay().ok().flatten()
        };
        let runtime_label = fasttab_model
            .as_ref()
            .map(|_| "lm2-fasttab-onnx:f116c14b256d3".to_owned())
            .or_else(|| {
                native_catboost_model.as_ref().map(|model| {
                    format!(
                        "lm2-native-catboost-text-runtime:f{}c{}t{}d{}:sha{}",
                        model.float_feature_count,
                        model.cat_feature_count,
                        model.text_feature_count,
                        model.dimensions_count,
                        &model.model_sha256[..16]
                    )
                })
            })
            .or_else(|| {
                numeric_catboost_model.as_ref().map(|_| {
                    let source =
                        std::env::var("LAWPDF_LM2_NUMERIC_CATBOOST_MODEL").unwrap_or_default();
                    format!("lm2-numeric-catboost-runtime:{:016x}", fnv1a64(&source))
                })
            });
        match load_lm2_model() {
            Ok(model) if model_is_usable(&model) => Self {
                model_label: runtime_label.unwrap_or_else(|| model.model_id.clone()),
                load_warnings,
                model: Some(model),
                fasttab_model,
                native_catboost_model,
                context_twopass_model,
                context_arbiter_model,
                note_head_model,
                link_ranker_model,
                numeric_catboost_model,
                static_front_overlay,
                pp_priors,
                pp_footnote_region_membership: !native_line_model_active
                    && lm2_pp_footnote_region_membership_enabled(),
                marker_decoder_prior: !native_line_model_active
                    && lm2_marker_decoder_prior_enabled(),
                small_font_decoder_prior: !native_line_model_active
                    && lm2_small_font_decoder_prior_enabled(),
                small_font_sequence_prior: !native_line_model_active
                    && lm2_small_font_sequence_prior_enabled(),
                anchored_marginalia_flow_guard: !native_line_model_active
                    && lm2_anchored_marginalia_flow_guard_enabled(),
                body_preservation_guard: !native_line_model_active
                    && lm2_body_preservation_guard_enabled(),
                action_neutral_blocksplit: !native_line_model_active
                    && lm2_action_neutral_blocksplit_enabled(),
                toc_overlay: !native_line_model_active && lm2_toc_overlay_enabled(),
                front_matter_guard: !native_line_model_active && lm2_front_matter_guard_enabled(),
                marginalia_preservation_guard: !native_line_model_active
                    && lm2_marginalia_preservation_guard_enabled(),
                start_score_scale: if native_line_model_active {
                    1.0
                } else {
                    lm2_start_score_scale()
                },
                transition_score_scale: if native_line_model_active {
                    1.0
                } else {
                    lm2_transition_score_scale()
                },
            },
            _ => Self {
                model: None,
                fasttab_model,
                model_label: runtime_label.unwrap_or_else(|| "lm2-heuristic-fallback".to_owned()),
                load_warnings,
                native_catboost_model,
                context_twopass_model,
                context_arbiter_model,
                note_head_model,
                link_ranker_model,
                numeric_catboost_model,
                static_front_overlay,
                pp_priors,
                pp_footnote_region_membership: !native_line_model_active
                    && lm2_pp_footnote_region_membership_enabled(),
                marker_decoder_prior: !native_line_model_active
                    && lm2_marker_decoder_prior_enabled(),
                small_font_decoder_prior: !native_line_model_active
                    && lm2_small_font_decoder_prior_enabled(),
                small_font_sequence_prior: !native_line_model_active
                    && lm2_small_font_sequence_prior_enabled(),
                anchored_marginalia_flow_guard: !native_line_model_active
                    && lm2_anchored_marginalia_flow_guard_enabled(),
                body_preservation_guard: !native_line_model_active
                    && lm2_body_preservation_guard_enabled(),
                action_neutral_blocksplit: !native_line_model_active
                    && lm2_action_neutral_blocksplit_enabled(),
                toc_overlay: !native_line_model_active && lm2_toc_overlay_enabled(),
                front_matter_guard: !native_line_model_active && lm2_front_matter_guard_enabled(),
                marginalia_preservation_guard: !native_line_model_active
                    && lm2_marginalia_preservation_guard_enabled(),
                start_score_scale: if native_line_model_active {
                    1.0
                } else {
                    lm2_start_score_scale()
                },
                transition_score_scale: if native_line_model_active {
                    1.0
                } else {
                    lm2_transition_score_scale()
                },
            },
        }
    }

    fn emission_scores(&self, line: &DeepLiquidSourceLine) -> [f64; 3] {
        if let Some(model) = self.fasttab_model.as_ref()
            && let Ok(scores) = model.emission_scores(std::slice::from_ref(line))
            && let Some(scores) = scores.first()
        {
            return *scores;
        }
        if let Some(model) = self.native_catboost_model.as_ref() {
            return model.emission_scores(line).unwrap_or([0.0, 0.0, 0.0]);
        }
        let mut scores = if let Some(model) = self.numeric_catboost_model.as_ref() {
            model.emission_scores(line)
        } else if let Some(model) = self.model.as_ref() {
            let features = lm2_features(
                line,
                model.feature_dim,
                model.doc_font_zscores_enabled(),
                model.repetition_fingerprints_enabled(),
                model.marker_continuity_enabled(),
            );
            let mut scores = [0.0, 0.0, 0.0];
            for (index, score) in scores.iter_mut().enumerate() {
                *score = *model.bias.get(index).unwrap_or(&0.0);
            }
            for (feature_index, value) in features {
                for (class_index, score) in scores.iter_mut().enumerate() {
                    if let Some(weight) = model
                        .weights
                        .get(class_index)
                        .and_then(|weights| weights.get(feature_index))
                    {
                        *score += weight * value;
                    }
                }
            }
            scores
        } else {
            [0.0, 0.0, 0.0]
        };
        apply_layout_priors(line, &mut scores);
        apply_pp_priors(self, line, &mut scores);
        scores
    }

    fn native_line_model_active(&self) -> bool {
        self.fasttab_model.is_some() || self.native_catboost_model.is_some()
    }

    fn decoder_weights(&self) -> Option<&HashMap<String, f64>> {
        self.model
            .as_ref()
            .and_then(|model| model.decoder_constants.as_ref())
            .map(|constants| &constants.weights)
            .filter(|weights| !weights.is_empty())
    }

    fn pp_prior_for_line(&self, line: &DeepLiquidSourceLine) -> Option<Lm2PpPrior> {
        line.pp_prior_score.map(|score| Lm2PpPrior {
            role: line.pp_prior_role.clone().unwrap_or_default(),
            label: line.pp_prior_label.clone().unwrap_or_default(),
            score,
        })
    }

    fn pp_prior_source(&self) -> Option<String> {
        self.pp_priors
            .as_ref()
            .map(|index| index.source.display().to_string())
    }
}

fn argmax_lm2_action(scores: [f64; 3]) -> Lm2Action {
    ACTIONS
        .into_iter()
        .max_by(|left, right| {
            scores[left.index()]
                .partial_cmp(&scores[right.index()])
                .unwrap_or(Ordering::Equal)
        })
        .unwrap_or(Lm2Action::Keep)
}

impl Lm2ContextTwopassModel {
    fn label(&self) -> String {
        if matches!(
            self.schema_version.as_str(),
            LM2_CONTEXT_ARBITER_SCHEMA_V2 | LM2_CONTEXT_RESIDUAL_SCHEMA_V3
        ) {
            let primary = self
                .primary_model_sha256
                .as_deref()
                .unwrap_or("unknown")
                .chars()
                .take(12)
                .collect::<String>();
            let asset = self.asset_sha256.chars().take(12).collect::<String>();
            let runtime_version = if self.schema_version == LM2_CONTEXT_RESIDUAL_SCHEMA_V3 {
                LM2_CONTEXT_RESIDUAL_RUNTIME_VERSION
            } else {
                LM2_CONTEXT_ARBITER_RUNTIME_VERSION
            };
            return format!(
                "{}:{}:a{}f{}m{}:primary{}:asset{}",
                runtime_version,
                self.schema_version,
                self.actions.len(),
                self.feature_count,
                self.models.len(),
                primary,
                asset
            );
        }
        format!(
            "{LM2_CONTEXT_TWOPASS_VERSION}:{}:a{}f{}m{}",
            self.schema_version,
            self.actions.len(),
            self.feature_count,
            self.models.len()
        )
    }

    fn model_for_document(&self, document_path: &Path) -> Option<&Lm2ContextTwopassHgbModel> {
        let normalized = lm2_context_norm_path(&document_path.display().to_string());
        if let Some(fold) = self.doc_to_fold.get(&normalized) {
            let name = format!("fold{fold}");
            if let Some(model) = self.models.iter().find(|model| model.name == name) {
                return Some(model);
            }
        }
        self.models
            .iter()
            .find(|model| model.name == self.unseen_doc_model)
            .or_else(|| self.models.first())
    }
}

impl Lm2ContextTwopassHgbModel {
    fn raw_prediction(&self, features: &[f64]) -> [f64; 3] {
        let mut raw = [0.0; 3];
        for (index, score) in raw.iter_mut().enumerate() {
            *score = *self.baseline_prediction.get(index).unwrap_or(&0.0);
        }
        for iteration in &self.trees {
            for (class_index, tree) in iteration.iter().take(3).enumerate() {
                raw[class_index] += lm2_context_tree_predict(tree, features);
            }
        }
        raw
    }

    fn predict(&self, features: &[f64]) -> Lm2Action {
        let raw = self.raw_prediction(features);
        let class_index = raw
            .iter()
            .enumerate()
            .max_by(|(_, left), (_, right)| left.partial_cmp(right).unwrap_or(Ordering::Equal))
            .map(|(index, _)| index)
            .unwrap_or(1);
        match class_index {
            0 => Lm2Action::HideNoise,
            1 => Lm2Action::Keep,
            2 => Lm2Action::Marginalia,
            _ => Lm2Action::Keep,
        }
    }

    fn predict_probabilities(&self, features: &[f64]) -> [f64; 3] {
        lm2_context_softmax(self.raw_prediction(features))
    }
}

impl Lm2NoteHeadModel {
    fn label(&self) -> String {
        let asset = self.asset_sha256.chars().take(12).collect::<String>();
        let primary = self
            .primary_model_sha256
            .as_deref()
            .map(|sha| sha.chars().take(12).collect::<String>())
            .unwrap_or_else(|| "none".to_owned());
        format!(
            "{LM2_NOTE_HEAD_RUNTIME_VERSION}:{}:f{}t{}:primary{primary}:asset{asset}",
            self.schema_version,
            self.feature_count,
            self.trees.len(),
        )
    }

    fn probability(&self, features: &[f64]) -> f64 {
        let raw = self
            .trees
            .iter()
            .fold(self.baseline_prediction, |score, tree| {
                score + lm2_context_tree_predict(tree, features)
            });
        if raw >= 0.0 {
            1.0 / (1.0 + (-raw).exp())
        } else {
            let exp = raw.exp();
            exp / (1.0 + exp)
        }
    }
}

impl Lm2LinkRankerModel {
    fn label(&self) -> String {
        let asset = self.asset_sha256.chars().take(12).collect::<String>();
        let auth = self.auth_model_sha256.chars().take(12).collect::<String>();
        format!(
            "{LM2_LINK_RANKER_RUNTIME_VERSION}:{LM2_LINK_RANKER_SCHEMA_V1}:f{}t{}:auth{auth}:asset{asset}",
            LM2_LINK_RANKER_FEATURE_COUNT_V1,
            self.trees.len(),
        )
    }

    fn probability(&self, features: &[f64]) -> f64 {
        let raw = self
            .trees
            .iter()
            .fold(self.baseline_prediction, |score, tree| {
                score + lm2_context_tree_predict(tree, features)
            });
        if raw >= 0.0 {
            1.0 / (1.0 + (-raw).exp())
        } else {
            let exp = raw.exp();
            exp / (1.0 + exp)
        }
    }
}

fn lm2_context_softmax(raw: [f64; 3]) -> [f64; 3] {
    let max = raw.into_iter().fold(f64::NEG_INFINITY, f64::max);
    let exp = raw.map(|value| (value - max).exp());
    let total = exp.iter().sum::<f64>();
    if total.is_finite() && total > 0.0 {
        exp.map(|value| value / total)
    } else {
        [0.0, 1.0, 0.0]
    }
}

fn lm2_context_tree_predict(nodes: &[[f64; 7]], features: &[f64]) -> f64 {
    let mut index = 0usize;
    for _ in 0..nodes.len() {
        let Some(node) = nodes.get(index) else {
            return 0.0;
        };
        if node[6] != 0.0 {
            return node[0];
        }
        let feature_index = node[1] as usize;
        let threshold = node[2];
        let value = *features.get(feature_index).unwrap_or(&0.0);
        let go_left = if value.is_nan() {
            node[3] != 0.0
        } else {
            value <= threshold
        };
        index = if go_left {
            node[4] as usize
        } else {
            node[5] as usize
        };
    }
    0.0
}

fn apply_context_twopass_model(
    model: &Lm2ContextTwopassModel,
    document_path: &Path,
    primary_emissions: Option<&[[f64; 3]]>,
    decoded: &mut [(DeepLiquidSourceLine, Lm2Action)],
) {
    if decoded.is_empty() {
        return;
    }
    let Some(document_model) = model.model_for_document(document_path) else {
        return;
    };
    if matches!(
        model.schema_version.as_str(),
        LM2_CONTEXT_ARBITER_SCHEMA_V2 | LM2_CONTEXT_RESIDUAL_SCHEMA_V3
    ) {
        let Some(primary_emissions) = primary_emissions.filter(|rows| rows.len() == decoded.len())
        else {
            return;
        };
        let baseline_actions = decoded
            .iter()
            .map(|(_, action)| *action)
            .collect::<Vec<_>>();
        let primary_probabilities = primary_emissions
            .iter()
            .copied()
            .map(lm2_context_primary_probabilities)
            .collect::<Vec<_>>();
        let Some(calibration) = model.calibration.as_ref() else {
            return;
        };
        for index in 0..decoded.len() {
            let features = if model.schema_version == LM2_CONTEXT_RESIDUAL_SCHEMA_V3 {
                lm2_context_runtime_residual_feature_vector(
                    decoded,
                    &primary_probabilities,
                    baseline_actions[index],
                    index,
                )
            } else {
                lm2_context_arbiter_feature_vector(decoded, &primary_probabilities, index)
            };
            if features.len() != model.feature_count {
                continue;
            }
            let arbiter = document_model.predict_probabilities(&features);
            let prediction = if model.schema_version == LM2_CONTEXT_RESIDUAL_SCHEMA_V3 {
                lm2_context_runtime_residual_policy(
                    baseline_actions[index],
                    arbiter,
                    calibration,
                    &decoded[index].0.text,
                )
            } else {
                lm2_context_arbiter_policy(baseline_actions[index], arbiter, calibration)
            };
            decoded[index].1 = prediction;
        }
        return;
    }
    let baseline_actions = decoded
        .iter()
        .map(|(_, action)| *action)
        .collect::<Vec<_>>();
    let block_meta = lm2_context_block_meta(decoded);
    for index in 0..decoded.len() {
        let features = lm2_context_feature_vector(decoded, &baseline_actions, &block_meta, index);
        if features.len() == model.feature_count {
            decoded[index].1 = document_model.predict(&features);
        }
    }
}

fn lm2_context_primary_probabilities(internal_scores: [f64; 3]) -> [f64; 3] {
    // Native inference is [keep, marginalia, hide_noise], whereas the arbiter's
    // training/export contract is [hide_noise, keep, marginalia].
    lm2_context_softmax([
        internal_scores[Lm2Action::HideNoise.index()],
        internal_scores[Lm2Action::Keep.index()],
        internal_scores[Lm2Action::Marginalia.index()],
    ])
}

fn lm2_context_finite_feature(value: f64) -> f64 {
    if value.is_nan() {
        0.0
    } else if value == f64::INFINITY {
        1_000_000.0
    } else if value == f64::NEG_INFINITY {
        -1_000_000.0
    } else {
        value
    }
}

fn lm2_context_arbiter_feature_vector(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    primary_probabilities: &[[f64; 3]],
    index: usize,
) -> Vec<f64> {
    let mut features = Vec::with_capacity(LM2_CONTEXT_ARBITER_FEATURE_COUNT_V2);
    let feature_map = lm2_numeric_catboost_features(&decoded[index].0);
    features.extend(
        LM2_NATIVE_CATBOOST_FLOAT_FEATURES
            .iter()
            .map(|name| lm2_context_finite_feature(feature_map.get(*name).copied().unwrap_or(0.0))),
    );
    features.extend(primary_probabilities[index]);

    let mut neighbor_meta = Vec::with_capacity(LM2_CONTEXT_ARBITER_NEIGHBOR_OFFSETS.len());
    for offset in LM2_CONTEXT_ARBITER_NEIGHBOR_OFFSETS {
        let neighbor = index.checked_add_signed(offset).filter(|neighbor| {
            decoded
                .get(*neighbor)
                .is_some_and(|(line, _)| line.page_index == decoded[index].0.page_index)
        });
        if let Some(neighbor) = neighbor {
            features.extend(primary_probabilities[neighbor]);
            let gap = decoded[index]
                .0
                .line_index
                .abs_diff(decoded[neighbor].0.line_index)
                .min(8) as f64
                / 8.0;
            neighbor_meta.push((1.0, gap));
        } else {
            features.extend([0.0; 3]);
            neighbor_meta.push((0.0, 0.0));
        }
    }
    features.extend(neighbor_meta.iter().map(|(same_page, _)| *same_page));
    features.extend(neighbor_meta.iter().map(|(_, gap)| *gap));
    features
}

fn lm2_context_runtime_residual_feature_vector(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    primary_probabilities: &[[f64; 3]],
    baseline_action: Lm2Action,
    index: usize,
) -> Vec<f64> {
    let mut features = lm2_context_arbiter_feature_vector(decoded, primary_probabilities, index);
    features.reserve(3);
    lm2_context_onehot(&mut features, Some(baseline_action));
    features
}

fn lm2_context_has_substantive_text(text: &str) -> bool {
    text.chars().any(char::is_alphabetic)
}

fn lm2_note_head_feature_vector(
    line: &DeepLiquidSourceLine,
    primary_probabilities: Option<[f64; 3]>,
) -> Option<(u16, Vec<f64>)> {
    let (marker, normalized_text) = lm2_note_head_normalized_text(&line.text)?;
    let trimmed = normalized_text.as_str();
    let digit_count = trimmed
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .take(3)
        .count();
    let suffix = trimmed.chars().nth(digit_count)?;
    let remainder = trimmed
        .chars()
        .skip(digit_count + 1)
        .skip_while(|ch| ch.is_whitespace())
        .collect::<String>();
    let first = remainder.chars().next();
    let text_chars = normalized_text.chars().count().max(1);
    let text_digits = normalized_text
        .chars()
        .filter(|ch| ch.is_ascii_digit())
        .count();
    let token_count = normalized_text.split_whitespace().count();
    let mut features =
        Vec::with_capacity(LM2_NOTE_HEAD_FEATURE_COUNT_V1 + primary_probabilities.map_or(0, |_| 3));
    let feature_map = lm2_numeric_catboost_features(line);
    features.extend(
        LM2_NATIVE_CATBOOST_FLOAT_FEATURES
            .iter()
            .map(|name| lm2_context_finite_feature(feature_map.get(*name).copied().unwrap_or(0.0))),
    );
    if let Some(probabilities) = primary_probabilities {
        features.extend(probabilities);
    }
    features.extend([
        marker as f64 / 500.0,
        (marker as f64).ln_1p() / 501.0f64.ln(),
        digit_count as f64 / 3.0,
        text_chars.min(500) as f64 / 500.0,
        token_count.min(100) as f64 / 100.0,
        text_digits as f64 / text_chars as f64,
        bool_as_f64(suffix.is_whitespace()),
        bool_as_f64(suffix == '.'),
        bool_as_f64(suffix == ')'),
        bool_as_f64(suffix == ']'),
        bool_as_f64(first.is_some_and(char::is_uppercase)),
        bool_as_f64(first.is_some_and(char::is_lowercase)),
        bool_as_f64(first.is_some_and(|ch| ch.is_ascii_digit())),
        bool_as_f64(marker <= 5),
        bool_as_f64(marker >= 100),
    ]);
    Some((marker, features))
}

fn lm2_note_head_normalized_text(text: &str) -> Option<(u16, String)> {
    let trimmed = text.trim_start();
    if let Some(marker) = leading_numeric_token_marker(trimmed) {
        return Some((marker, trimmed.to_owned()));
    }
    let mut chars = trimmed.char_indices();
    if chars.next().map(|(_, ch)| ch) != Some(CALLOUT_START) {
        return None;
    }
    let mut digits = String::new();
    let mut end = None;
    for (index, ch) in chars {
        if ch == CALLOUT_END {
            end = Some(index + ch.len_utf8());
            break;
        }
        if !ch.is_ascii_digit() || digits.len() >= 3 {
            return None;
        }
        digits.push(ch);
    }
    let marker = digits.parse::<u16>().ok()?;
    if !(1..=LM2_MAX_NOTE_MARKER).contains(&marker) {
        return None;
    }
    let remainder = trimmed.get(end?..)?.trim_start();
    Some((marker, format!("{marker} {remainder}")))
}

fn lm2_note_head_sequence_features(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    primary_probabilities: &[[f64; 3]],
) -> Vec<Option<[f64; 16]>> {
    let mut candidates = decoded
        .iter()
        .enumerate()
        .filter_map(|(index, (line, _))| {
            lm2_note_head_normalized_text(&line.text)
                .map(|(marker, _)| (index, marker, line.page_index, line.line_index))
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|(index, _, page, line)| (*page, *line, *index));
    let mut output = vec![None; decoded.len()];
    for (position, (index, marker, page, line)) in candidates.iter().copied().enumerate() {
        let mut features = [0.0; 16];
        for (slot, offset) in LM2_NOTE_HEAD_NEIGHBOR_OFFSETS_V3.into_iter().enumerate() {
            let Some(neighbor_position) = position.checked_add_signed(offset) else {
                continue;
            };
            let Some((neighbor_index, neighbor_marker, neighbor_page, neighbor_line)) =
                candidates.get(neighbor_position).copied()
            else {
                continue;
            };
            let cursor = slot * 8;
            let same_page = neighbor_page == page;
            features[cursor] = 1.0;
            features[cursor + 1] =
                (neighbor_marker as i32 - marker as i32).clamp(-20, 20) as f64 / 20.0;
            features[cursor + 2] = (neighbor_page as i64 - page as i64).clamp(-4, 4) as f64 / 4.0;
            features[cursor + 3] = if same_page {
                neighbor_line.abs_diff(line).min(50) as f64 / 50.0
            } else {
                1.0
            };
            features[cursor + 4] = bool_as_f64(same_page);
            if let Some(probabilities) = primary_probabilities.get(neighbor_index) {
                features[cursor + 5..cursor + 8].copy_from_slice(probabilities);
            }
        }
        output[index] = Some(features);
    }
    output
}

#[derive(Debug, Clone, Copy)]
struct Lm2LinkNumericCandidate {
    decoded_index: usize,
    marker: u16,
}

fn lm2_link_numeric_candidates(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
) -> Vec<Lm2LinkNumericCandidate> {
    let mut candidates = decoded
        .iter()
        .enumerate()
        .filter_map(|(decoded_index, (line, _))| {
            lm2_note_head_normalized_text(&line.text).map(|(marker, _)| Lm2LinkNumericCandidate {
                decoded_index,
                marker,
            })
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|candidate| {
        let line = &decoded[candidate.decoded_index].0;
        (line.page_index, line.line_index, candidate.decoded_index)
    });
    candidates
}

fn lm2_note_head_auth_probabilities(
    model: &Lm2NoteHeadModel,
    document_path: &Path,
    primary_emissions: &[[f64; 3]],
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
) -> Vec<Option<(u16, f64)>> {
    if model.schema_version != LM2_NOTE_HEAD_SCHEMA_V3 || primary_emissions.len() != decoded.len() {
        return vec![None; decoded.len()];
    }
    let primary_probabilities = primary_emissions
        .iter()
        .copied()
        .map(lm2_context_primary_probabilities)
        .collect::<Vec<_>>();
    let sequence_features = lm2_note_head_sequence_features(decoded, &primary_probabilities);
    let trace_path = std::env::var_os("LAWPDF_LM2_TRACE_NOTE_HEAD_FILE").map(PathBuf::from);
    let mut trace_rows = Vec::new();
    let mut output = Vec::with_capacity(decoded.len());
    for (index, (line, action)) in decoded.iter().enumerate() {
        let Some((marker, mut features)) =
            lm2_note_head_feature_vector(line, Some(primary_probabilities[index]))
        else {
            output.push(None);
            continue;
        };
        if let Some(sequence) = sequence_features.get(index).copied().flatten() {
            features.extend(sequence);
        }
        if features.len() != model.feature_count {
            output.push(None);
            continue;
        }
        let probability = model.probability(&features);
        if trace_path.is_some() {
            trace_rows.push(serde_json::json!({
                "document": document_path.display().to_string(),
                "id": line.id.clone(),
                "page_index": line.page_index,
                "line_index": line.line_index,
                "marker": marker,
                "probability": probability,
                "threshold": model.threshold,
                "primary_probabilities": primary_probabilities[index],
                "features": features,
                "baseline_action": action.as_str(),
                "text": line.text.clone(),
            }));
        }
        output.push(Some((marker, probability)));
    }
    if let Some(path) = trace_path
        && !trace_rows.is_empty()
        && let Ok(file) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
    {
        use std::io::Write as _;
        let mut writer = std::io::BufWriter::new(file);
        for row in trace_rows {
            if let Ok(encoded) = serde_json::to_string(&row) {
                let _ = writeln!(writer, "{encoded}");
            }
        }
        let _ = writer.flush();
    }
    output
}

fn lm2_link_text_contains_marker(text: &str, marker: u16) -> bool {
    if sentineled_note_markers(text).contains(&marker) {
        return true;
    }
    let chars = text.chars().collect::<Vec<_>>();
    let mut index = 0usize;
    while index < chars.len() {
        if !chars[index].is_ascii_digit() {
            index += 1;
            continue;
        }
        let start = index;
        while index < chars.len() && chars[index].is_ascii_digit() && index - start < 3 {
            index += 1;
        }
        let bounded_left = start == 0 || !chars[start - 1].is_ascii_digit();
        let bounded_right = index == chars.len() || !chars[index].is_ascii_digit();
        let value = chars[start..index]
            .iter()
            .collect::<String>()
            .parse::<u16>()
            .ok();
        if bounded_left && bounded_right && value == Some(marker) {
            return true;
        }
    }
    false
}

fn lm2_link_neighbor_features(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    candidate: Lm2LinkNumericCandidate,
    neighbor: Option<Lm2LinkNumericCandidate>,
) -> [f64; 6] {
    let Some(neighbor) = neighbor else {
        return [0.0; 6];
    };
    let line = &decoded[candidate.decoded_index].0;
    let other = &decoded[neighbor.decoded_index].0;
    let same_page = line.page_index == other.page_index;
    [
        1.0,
        (neighbor.marker as i32 - candidate.marker as i32).clamp(-20, 20) as f64 / 20.0,
        (other.page_index as i64 - line.page_index as i64).clamp(-4, 4) as f64 / 4.0,
        if same_page {
            other.line_index.abs_diff(line.line_index).min(100) as f64 / 100.0
        } else {
            1.0
        },
        bool_as_f64(same_page),
        bool_as_f64(decoded[neighbor.decoded_index].1 == Lm2Action::Marginalia),
    ]
}

fn lm2_link_note_neighbor_features(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    candidate: Lm2LinkNumericCandidate,
    neighbor: Option<Lm2LinkNumericCandidate>,
) -> [f64; 4] {
    let Some(neighbor) = neighbor else {
        return [0.0; 4];
    };
    let line = &decoded[candidate.decoded_index].0;
    let other = &decoded[neighbor.decoded_index].0;
    let same_page = line.page_index == other.page_index;
    [
        1.0,
        (neighbor.marker as i32 - candidate.marker as i32).clamp(-20, 20) as f64 / 20.0,
        (other.page_index as i64 - line.page_index as i64).clamp(-8, 8) as f64 / 8.0,
        if same_page {
            other.line_index.abs_diff(line.line_index).min(100) as f64 / 100.0
        } else {
            1.0
        },
    ]
}

fn lm2_link_ranker_feature_vector(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    candidates: &[Lm2LinkNumericCandidate],
    candidate_position: usize,
    reference_index: usize,
    local_same_marker_count: usize,
    document_same_marker_count: usize,
    auth_probability: f64,
) -> Vec<f64> {
    let candidate = candidates[candidate_position];
    let line = &decoded[candidate.decoded_index].0;
    let reference = &decoded[reference_index].0;
    let page_count = decoded
        .iter()
        .map(|(line, _)| line.page_index)
        .max()
        .map_or(1, |page| page + 1);
    let page_max_line = decoded
        .iter()
        .filter(|(other, _)| other.page_index == line.page_index)
        .map(|(other, _)| other.line_index)
        .max()
        .unwrap_or(line.line_index)
        .max(1);
    let width = (line.page_width as f64).max(1.0);
    let height = (line.page_height as f64).max(1.0);
    let page_delta = line.page_index as i64 - reference.page_index as i64;
    let (_, normalized_text) =
        lm2_note_head_normalized_text(&line.text).unwrap_or((candidate.marker, line.text.clone()));
    let digit_count = normalized_text
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .take(3)
        .count();
    let suffix = normalized_text.chars().nth(digit_count).unwrap_or(' ');
    let remainder = normalized_text
        .chars()
        .skip(digit_count + 1)
        .skip_while(|ch| ch.is_whitespace())
        .collect::<String>();
    let text_chars = normalized_text.chars().count().max(1);
    let digit_chars = normalized_text
        .chars()
        .filter(|ch| ch.is_ascii_digit())
        .count();
    let alpha_chars = normalized_text
        .chars()
        .filter(|ch| ch.is_alphabetic())
        .collect::<Vec<_>>();
    let uppercase_chars = alpha_chars.iter().filter(|ch| ch.is_uppercase()).count();
    let punctuation_chars = normalized_text
        .chars()
        .filter(|ch| !ch.is_alphanumeric() && !ch.is_whitespace())
        .count();
    let whitespace_chars = normalized_text
        .chars()
        .filter(|ch| ch.is_whitespace())
        .count();
    let reference_starts = lm2_note_head_normalized_text(&reference.text)
        .is_some_and(|(marker, _)| marker == candidate.marker);
    let reference_has_marker = lm2_link_text_contains_marker(&reference.text, candidate.marker);
    let reference_words = reference.text.split_whitespace().count();
    let same_reference_page = line.page_index == reference.page_index;
    let segment_count = line.segment_block_line_count.max(1);
    let previous = candidate_position
        .checked_sub(1)
        .and_then(|position| candidates.get(position))
        .copied();
    let next = candidates.get(candidate_position + 1).copied();
    let coordinate = (line.page_index, line.line_index, candidate.decoded_index);
    let current_notes = candidates
        .iter()
        .copied()
        .filter(|other| decoded[other.decoded_index].1 == Lm2Action::Marginalia)
        .collect::<Vec<_>>();
    let previous_note = current_notes.iter().copied().rev().find(|other| {
        let other_line = &decoded[other.decoded_index].0;
        (
            other_line.page_index,
            other_line.line_index,
            other.decoded_index,
        ) < coordinate
    });
    let next_note = current_notes.iter().copied().find(|other| {
        let other_line = &decoded[other.decoded_index].0;
        (
            other_line.page_index,
            other_line.line_index,
            other.decoded_index,
        ) > coordinate
    });
    let previous_consecutive =
        previous_note.is_some_and(|other| other.marker + 1 == candidate.marker);
    let next_consecutive = next_note.is_some_and(|other| candidate.marker + 1 == other.marker);
    let first_remainder = remainder.chars().next();
    let lower_remainder = remainder.to_lowercase();
    let terminal_punctuation = remainder
        .trim_end()
        .chars()
        .last()
        .is_some_and(|ch| matches!(ch, '.' | '?' | '!' | ';' | ':'));

    let mut features = vec![
        candidate.marker as f64 / 500.0,
        (candidate.marker as f64).ln_1p() / 501.0f64.ln(),
        candidate.marker.to_string().len() as f64 / 3.0,
        bool_as_f64(candidate.marker <= 5),
        bool_as_f64(candidate.marker >= 100),
        page_delta.clamp(-4, 4) as f64 / 4.0,
        bool_as_f64(page_delta == 0),
        bool_as_f64(page_delta == 1),
        reference.page_index as f64 / page_count.saturating_sub(1).max(1) as f64,
        line.page_index as f64 / page_count.saturating_sub(1).max(1) as f64,
        1.0,
        bool_as_f64(reference_starts),
        bool_as_f64(reference_has_marker && !reference_starts),
        reference_words.min(100) as f64 / 100.0,
        reference.font_ratio_page as f64,
        bool_as_f64(line.id == reference.id),
        bool_as_f64(
            (line.page_index, line.line_index) > (reference.page_index, reference.line_index),
        ),
        if same_reference_page {
            (line.line_index as i64 - reference.line_index as i64).clamp(-100, 100) as f64 / 100.0
        } else {
            0.0
        },
        line.line_index as f64 / page_max_line as f64,
        line.top as f64 / height,
        line.bottom as f64 / height,
        ((line.top + line.bottom) as f64 * 0.5) / height,
        (line.right - line.left).max(0.0) as f64 / width,
        line.left as f64 / width,
        (line.page_width - line.right).max(0.0) as f64 / width,
        line.font_ratio_page as f64,
        line.font_ratio_page_ref as f64,
        line.font_ratio_doc as f64,
        line.font_height as f64 / height,
        bool_as_f64(line.bold),
        bool_as_f64(line.italic),
        bool_as_f64(line.centered),
        bool_as_f64(line.margin_centered),
        bool_as_f64(line.below_footnote_divider),
        bool_as_f64(line.page_has_footnote_divider),
        bool_as_f64(line.in_footnote_zone),
        bool_as_f64(line.doc_footnote_state),
        bool_as_f64(line.doc_footnote_continuation),
        bool_as_f64(line.segment_block_footnote_like),
        bool_as_f64(line.segment_block_furniture_like),
        bool_as_f64(line.segment_block_table_like),
        bool_as_f64(line.segment_block_toc_like),
        bool_as_f64(line.segment_block_first),
        bool_as_f64(line.segment_block_last),
        line.segment_block_line_index as f64 / segment_count.saturating_sub(1).max(1) as f64,
        segment_count.min(50) as f64 / 50.0,
        text_chars.min(500) as f64 / 500.0,
        normalized_text.split_whitespace().count().min(100) as f64 / 100.0,
        digit_chars as f64 / text_chars as f64,
        alpha_chars.len() as f64 / text_chars as f64,
        uppercase_chars as f64 / alpha_chars.len().max(1) as f64,
        punctuation_chars as f64 / text_chars as f64,
        whitespace_chars as f64 / text_chars as f64,
        bool_as_f64(suffix.is_whitespace()),
        bool_as_f64(suffix == '.'),
        bool_as_f64(suffix == ')'),
        bool_as_f64(suffix == ']'),
        bool_as_f64(first_remainder.is_some_and(char::is_uppercase)),
        bool_as_f64(first_remainder.is_some_and(char::is_lowercase)),
        bool_as_f64(first_remainder.is_some_and(|ch| ch.is_ascii_digit())),
        bool_as_f64(
            lower_remainder.contains("http://")
                || lower_remainder.contains("https://")
                || lower_remainder.contains("www."),
        ),
        bool_as_f64(terminal_punctuation),
        bool_as_f64(
            uppercase_chars as f64 / alpha_chars.len().max(1) as f64 >= 0.72
                && remainder.chars().count() >= 8,
        ),
        local_same_marker_count.min(8) as f64 / 8.0,
        document_same_marker_count.min(20) as f64 / 20.0,
    ];
    features.extend(lm2_link_neighbor_features(decoded, candidate, previous));
    features.extend(lm2_link_neighbor_features(decoded, candidate, next));
    features.extend(lm2_link_note_neighbor_features(
        decoded,
        candidate,
        previous_note,
    ));
    features.extend(lm2_link_note_neighbor_features(
        decoded, candidate, next_note,
    ));
    features.extend([
        bool_as_f64(previous_consecutive),
        bool_as_f64(next_consecutive),
        bool_as_f64(previous_consecutive && next_consecutive),
        auth_probability,
    ]);
    features
}

fn apply_footnote_link_ranker(
    link_model: &Lm2LinkRankerModel,
    auth_model: &Lm2NoteHeadModel,
    document_path: &Path,
    primary_emissions: Option<&[[f64; 3]]>,
    decoded: &mut [(DeepLiquidSourceLine, Lm2Action)],
) -> usize {
    let Some(primary_emissions) = primary_emissions.filter(|rows| rows.len() == decoded.len())
    else {
        return 0;
    };
    let candidates = lm2_link_numeric_candidates(decoded);
    if candidates.is_empty() {
        return 0;
    }
    let auth_probabilities =
        lm2_note_head_auth_probabilities(auth_model, document_path, primary_emissions, decoded);
    let mut candidate_counts_by_marker = HashMap::<u16, usize>::new();
    let mut candidate_positions_by_marker = HashMap::<u16, Vec<usize>>::new();
    let mut current_note_pages_by_marker = HashMap::<u16, HashSet<usize>>::new();
    for (position, candidate) in candidates.iter().copied().enumerate() {
        *candidate_counts_by_marker
            .entry(candidate.marker)
            .or_default() += 1;
        let line = &decoded[candidate.decoded_index].0;
        if decoded[candidate.decoded_index].1 == Lm2Action::Marginalia {
            current_note_pages_by_marker
                .entry(candidate.marker)
                .or_default()
                .insert(line.page_index);
            continue;
        }
        let auth_probability = auth_probabilities
            .get(candidate.decoded_index)
            .copied()
            .flatten()
            .map(|(_, probability)| probability)
            .unwrap_or(0.0);
        if auth_probability >= link_model.auth_threshold {
            candidate_positions_by_marker
                .entry(candidate.marker)
                .or_default()
                .push(position);
        }
    }
    let candidate_markers = candidate_positions_by_marker
        .keys()
        .copied()
        .collect::<HashSet<_>>();
    if candidate_markers.is_empty() {
        return 0;
    }
    let references = decoded
        .iter()
        .enumerate()
        .filter(|(_, (_, action))| *action == Lm2Action::Keep)
        .flat_map(|(index, (line, _))| {
            let leading_marker =
                lm2_note_head_normalized_text(&line.text).map(|(marker, _)| marker);
            let mut markers = sentineled_note_markers(&line.text)
                .into_iter()
                .filter(|marker| Some(*marker) != leading_marker)
                .collect::<HashSet<_>>();
            markers.extend(candidate_markers.iter().copied().filter(|marker| {
                Some(*marker) != leading_marker
                    && lm2_link_text_contains_marker(&line.text, *marker)
            }));
            markers.into_iter().map(move |marker| (index, marker))
        })
        .collect::<HashSet<_>>();
    let trace_path = std::env::var_os("LAWPDF_LM2_TRACE_LINK_RANKER_FILE").map(PathBuf::from);
    let mut trace_rows = Vec::new();
    let mut selected = HashSet::new();
    for (reference_index, marker) in references {
        let reference_page = decoded[reference_index].0.page_index;
        let already_resolved = current_note_pages_by_marker
            .get(&marker)
            .is_some_and(|pages| {
                pages.contains(&reference_page) || pages.contains(&(reference_page + 1))
            });
        if already_resolved {
            continue;
        }
        let local_positions = candidate_positions_by_marker
            .get(&marker)
            .into_iter()
            .flatten()
            .copied()
            .filter(|position| {
                let candidate = candidates[*position];
                let page = decoded[candidate.decoded_index].0.page_index;
                page == reference_page || page == reference_page + 1
            })
            .collect::<Vec<_>>();
        if local_positions.is_empty() {
            continue;
        }
        let document_same_marker_count = candidate_counts_by_marker
            .get(&marker)
            .copied()
            .unwrap_or(0);
        let mut scored = Vec::new();
        for position in &local_positions {
            let candidate = candidates[*position];
            let Some((_, auth_probability)) = auth_probabilities
                .get(candidate.decoded_index)
                .copied()
                .flatten()
            else {
                continue;
            };
            if auth_probability < link_model.auth_threshold {
                continue;
            }
            let features = lm2_link_ranker_feature_vector(
                decoded,
                &candidates,
                *position,
                reference_index,
                local_positions.len(),
                document_same_marker_count,
                auth_probability,
            );
            if features.len() != LM2_LINK_RANKER_FEATURE_COUNT_V1 {
                continue;
            }
            let link_probability = link_model.probability(&features);
            if trace_path.is_some() {
                let candidate_line = &decoded[candidate.decoded_index].0;
                let reference_line = &decoded[reference_index].0;
                trace_rows.push(serde_json::json!({
                    "document": document_path.display().to_string(),
                    "marker": marker,
                    "reference_id": reference_line.id.clone(),
                    "reference_page_index": reference_line.page_index,
                    "reference_line_index": reference_line.line_index,
                    "reference_text": reference_line.text.clone(),
                    "candidate_id": candidate_line.id.clone(),
                    "candidate_page_index": candidate_line.page_index,
                    "candidate_line_index": candidate_line.line_index,
                    "candidate_text": candidate_line.text.clone(),
                    "baseline_action": decoded[candidate.decoded_index].1.as_str(),
                    "auth_probability": auth_probability,
                    "auth_threshold": link_model.auth_threshold,
                    "link_probability": link_probability,
                    "link_threshold": link_model.threshold,
                    "features": features,
                }));
            }
            scored.push((candidate.decoded_index, auth_probability, link_probability));
        }
        scored.sort_by(|left, right| right.2.partial_cmp(&left.2).unwrap_or(Ordering::Equal));
        if let Some((candidate_index, auth_probability, link_probability)) = scored.first().copied()
            && auth_probability >= link_model.auth_threshold
            && link_probability >= link_model.threshold
        {
            selected.insert((candidate_index, marker));
        }
    }
    let changed = selected.len();
    for (index, marker) in selected {
        decoded[index].0.doc_note_marker = marker;
        decoded[index].1 = Lm2Action::Marginalia;
    }
    if let Some(path) = trace_path
        && !trace_rows.is_empty()
        && let Ok(file) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
    {
        use std::io::Write as _;
        let mut writer = std::io::BufWriter::new(file);
        for row in trace_rows {
            if let Ok(encoded) = serde_json::to_string(&row) {
                let _ = writeln!(writer, "{encoded}");
            }
        }
        let _ = writer.flush();
    }
    changed
}

fn apply_note_head_model(
    model: &Lm2NoteHeadModel,
    document_path: &Path,
    primary_emissions: Option<&[[f64; 3]]>,
    decoded: &mut [(DeepLiquidSourceLine, Lm2Action)],
) -> usize {
    let primary_emissions = primary_emissions.filter(|rows| rows.len() == decoded.len());
    let stacked = matches!(
        model.schema_version.as_str(),
        LM2_NOTE_HEAD_SCHEMA_V2 | LM2_NOTE_HEAD_SCHEMA_V3
    );
    if stacked && primary_emissions.is_none() {
        return 0;
    }
    let all_primary_probabilities = primary_emissions.map(|rows| {
        rows.iter()
            .copied()
            .map(lm2_context_primary_probabilities)
            .collect::<Vec<_>>()
    });
    let sequence_features = if model.schema_version == LM2_NOTE_HEAD_SCHEMA_V3 {
        all_primary_probabilities
            .as_deref()
            .map(|probabilities| lm2_note_head_sequence_features(decoded, probabilities))
    } else {
        None
    };
    let mut changed = 0usize;
    let trace = truthy_env("LAWPDF_LM2_TRACE_NOTE_HEAD");
    let trace_path = std::env::var_os("LAWPDF_LM2_TRACE_NOTE_HEAD_FILE").map(PathBuf::from);
    let mut trace_rows = Vec::new();
    for (index, (line, action)) in decoded.iter_mut().enumerate() {
        let primary_probabilities = if stacked {
            all_primary_probabilities
                .as_deref()
                .and_then(|rows| rows.get(index))
                .copied()
        } else {
            None
        };
        let Some((marker, mut features)) =
            lm2_note_head_feature_vector(line, primary_probabilities)
        else {
            if trace
                && (line.text.trim_start().starts_with(CALLOUT_START) || line.doc_note_marker > 0)
            {
                println!(
                    "note-head skipped page={} line={} marker={} action={} text={:?}",
                    line.page_index,
                    line.line_index,
                    line.doc_note_marker,
                    action.as_str(),
                    line.text
                );
            }
            continue;
        };
        if let Some(sequence) = sequence_features
            .as_ref()
            .and_then(|rows| rows.get(index))
            .copied()
            .flatten()
        {
            features.extend(sequence);
        }
        if features.len() != model.feature_count {
            continue;
        }
        let probability = model.probability(&features);
        if trace_path.is_some() {
            trace_rows.push(serde_json::json!({
                "document": document_path.display().to_string(),
                "id": line.id.clone(),
                "page_index": line.page_index,
                "line_index": line.line_index,
                "marker": marker,
                "probability": probability,
                "threshold": model.threshold,
                "primary_probabilities": primary_probabilities,
                "features": features,
                "baseline_action": action.as_str(),
                "text": line.text.clone(),
            }));
        }
        if trace {
            eprintln!(
                "note-head p={probability:.6} threshold={:.6} primary={primary_probabilities:?} page={} line={} action={} text={:?}",
                model.threshold,
                line.page_index,
                line.line_index,
                action.as_str(),
                line.text
            );
        }
        if probability < model.threshold {
            continue;
        }
        line.doc_note_marker = marker;
        if *action != Lm2Action::Marginalia {
            *action = Lm2Action::Marginalia;
            changed += 1;
        }
    }
    if let Some(path) = trace_path
        && !trace_rows.is_empty()
        && let Ok(file) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
    {
        use std::io::Write as _;
        let mut writer = std::io::BufWriter::new(file);
        for row in trace_rows {
            if let Ok(encoded) = serde_json::to_string(&row) {
                let _ = writeln!(writer, "{encoded}");
            }
        }
        let _ = writer.flush();
    }
    changed
}

fn lm2_context_arbiter_policy(
    baseline: Lm2Action,
    arbiter: [f64; 3],
    calibration: &Lm2ContextArbiterCalibration,
) -> Lm2Action {
    if baseline != Lm2Action::Keep {
        if arbiter[1] >= calibration.rescue_keep_threshold {
            return Lm2Action::Keep;
        }
        return if arbiter[0] >= arbiter[2] {
            if arbiter[0] >= calibration.reclassify_nonkeep_threshold {
                Lm2Action::HideNoise
            } else {
                baseline
            }
        } else if arbiter[2] >= calibration.reclassify_nonkeep_threshold {
            Lm2Action::Marginalia
        } else {
            baseline
        };
    }

    let mut prediction = Lm2Action::Keep;
    if arbiter[2] >= calibration.demote_to_marginalia_threshold {
        prediction = Lm2Action::Marginalia;
    }
    if arbiter[0] >= calibration.demote_to_noise_threshold {
        prediction = Lm2Action::HideNoise;
    }
    prediction
}

fn lm2_context_runtime_residual_policy(
    baseline: Lm2Action,
    residual: [f64; 3],
    calibration: &Lm2ContextArbiterCalibration,
    text: &str,
) -> Lm2Action {
    if baseline != Lm2Action::Keep
        && residual[1] >= calibration.rescue_keep_threshold
        && lm2_context_has_substantive_text(text)
    {
        Lm2Action::Keep
    } else {
        baseline
    }
}

fn lm2_context_norm_path(value: &str) -> String {
    value.trim().replace('\\', "/").to_ascii_lowercase()
}

fn lm2_context_action_index(action: Lm2Action) -> usize {
    match action {
        Lm2Action::HideNoise => 0,
        Lm2Action::Keep => 1,
        Lm2Action::Marginalia => 2,
    }
}

fn lm2_context_onehot(features: &mut Vec<f64>, action: Option<Lm2Action>) {
    let selected = action.map(lm2_context_action_index);
    for index in 0..3 {
        features.push(if selected == Some(index) { 1.0 } else { 0.0 });
    }
}

fn lm2_context_block_meta(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
) -> HashMap<String, Lm2ContextBlockMeta> {
    let page_count = decoded
        .iter()
        .map(|(line, _)| line.page_index)
        .max()
        .map_or(0, |page| page + 1);
    let article_spans = detect_lm2_article_spans(decoded, page_count);
    let (_, _, block_source_lines) =
        build_lm2_blocks_with_grouping("", decoded, None, &article_spans);
    let lines_by_id = decoded
        .iter()
        .map(|(line, _)| (line.id.clone(), line))
        .collect::<HashMap<_, _>>();
    let mut out = HashMap::new();
    for block in block_source_lines {
        let full_rows = block
            .lines
            .iter()
            .filter_map(|line| line.id.as_ref().and_then(|id| lines_by_id.get(id).copied()))
            .collect::<Vec<_>>();
        if full_rows.is_empty() {
            continue;
        }
        let n = full_rows.len().max(1) as f64;
        let block_text = full_rows
            .iter()
            .map(|line| collapse_whitespace(&line.text))
            .collect::<Vec<_>>()
            .join(" ");
        let shapes = full_rows
            .iter()
            .map(|line| lm2_context_text_shape(&collapse_whitespace(&line.text)))
            .collect::<Vec<_>>();
        let block_action = block
            .lines
            .iter()
            .map(|line| lm2_context_action_for_role(line.role))
            .collect::<Vec<_>>();
        let block_action = most_common_lm2_context_action(&block_action);
        let meta = Lm2ContextBlockMeta {
            block_action,
            block_line_count: full_rows.len(),
            block_char_count: block_text.chars().count(),
            block_short_ratio: shapes.iter().map(|shape| shape.short_text).sum::<f64>() / n,
            block_numeric_ratio: shapes
                .iter()
                .map(|shape| shape.numeric_or_roman)
                .sum::<f64>()
                / n,
            block_dotleader: if shapes.iter().any(|shape| shape.dotleader > 0.0) {
                1.0
            } else {
                0.0
            },
            block_note_start_ratio: shapes.iter().map(|shape| shape.note_start).sum::<f64>() / n,
            block_edge_ratio: full_rows
                .iter()
                .filter(|line| {
                    line.doc_repeated_top_edge
                        || line.doc_repeated_bottom_edge
                        || line.doc_repeated_edge_text
                })
                .count() as f64
                / n,
            block_axis_ratio: full_rows
                .iter()
                .filter(|line| {
                    line.doc_vertical_axis_like
                        || line.doc_vertical_numeric_axis_like
                        || line.page_table_column_like
                })
                .count() as f64
                / n,
            block_footzone_ratio: full_rows
                .iter()
                .filter(|line| line.in_footnote_zone || line.below_footnote_divider)
                .count() as f64
                / n,
            block_pos_norm: 0.0,
        };
        let denom = full_rows.len().saturating_sub(1).max(1) as f64;
        for (position, line) in full_rows.iter().enumerate() {
            let mut line_meta = meta.clone();
            line_meta.block_pos_norm = position as f64 / denom;
            out.insert(line.id.clone(), line_meta);
        }
    }
    out
}

fn most_common_lm2_context_action(actions: &[Lm2Action]) -> Option<Lm2Action> {
    ACTIONS
        .into_iter()
        .max_by_key(|candidate| actions.iter().filter(|action| *action == candidate).count())
}

fn lm2_context_action_for_role(role: LiquidBlockRole) -> Lm2Action {
    match role {
        LiquidBlockRole::Footnote | LiquidBlockRole::Marginalia => Lm2Action::Marginalia,
        LiquidBlockRole::Table
        | LiquidBlockRole::Caption
        | LiquidBlockRole::Contents
        | LiquidBlockRole::Header
        | LiquidBlockRole::Footer
        | LiquidBlockRole::Metadata
        | LiquidBlockRole::SectionBreak
        | LiquidBlockRole::Noise => Lm2Action::HideNoise,
        _ => Lm2Action::Keep,
    }
}

#[derive(Debug, Clone, Copy)]
struct Lm2ContextTextShape {
    char_count: f64,
    token_count: f64,
    short_text: f64,
    numeric_or_roman: f64,
    allcaps: f64,
    digit_ratio: f64,
    upper_ratio: f64,
    dotleader: f64,
    note_start: f64,
}

fn lm2_context_text_shape(text: &str) -> Lm2ContextTextShape {
    let chars = text.chars().count();
    let mut token_count = 0usize;
    let mut in_token = false;
    let mut ascii_letters = Vec::new();
    let mut digit_count = 0usize;
    for ch in text.chars() {
        let is_token = ch.is_ascii_alphanumeric() || ch == '§';
        if is_token && !in_token {
            token_count += 1;
        }
        in_token = is_token;
        if ch.is_ascii_alphabetic() {
            ascii_letters.push(ch);
        }
        if ch.is_ascii_digit() {
            digit_count += 1;
        }
    }
    let letter_count = ascii_letters.len();
    let upper_count = ascii_letters
        .iter()
        .filter(|ch| ch.is_ascii_uppercase())
        .count();
    let numeric_or_roman = !text.is_empty()
        && text.chars().count() <= 8
        && text.chars().all(|ch| {
            ch.is_ascii_digit()
                || matches!(
                    ch,
                    'I' | 'V'
                        | 'X'
                        | 'L'
                        | 'C'
                        | 'D'
                        | 'M'
                        | 'i'
                        | 'v'
                        | 'x'
                        | 'l'
                        | 'c'
                        | 'd'
                        | 'm'
                )
        });
    let allcaps = letter_count >= 8 && upper_count == letter_count;
    Lm2ContextTextShape {
        char_count: chars as f64,
        token_count: token_count as f64,
        short_text: if token_count <= 4 || chars <= 24 {
            1.0
        } else {
            0.0
        },
        numeric_or_roman: if numeric_or_roman { 1.0 } else { 0.0 },
        allcaps: if allcaps { 1.0 } else { 0.0 },
        digit_ratio: digit_count as f64 / chars.max(1) as f64,
        upper_ratio: upper_count as f64 / letter_count.max(1) as f64,
        dotleader: if lm2_context_has_dotleader(text) {
            1.0
        } else {
            0.0
        },
        note_start: if lm2_context_note_start(text) {
            1.0
        } else {
            0.0
        },
    }
}

fn lm2_context_has_dotleader(text: &str) -> bool {
    text.contains("...") || text.contains("···") || text.contains('…')
}

fn lm2_context_note_start(text: &str) -> bool {
    let trimmed = text.trim_start();
    let mut chars = trimmed.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if matches!(first, '*' | '†' | '‡' | '§') {
        return chars.next().is_some_and(char::is_whitespace);
    }
    if first.is_ascii_lowercase() {
        return chars.next() == Some(')') && chars.next().is_some_and(char::is_whitespace);
    }
    let mut rest = trimmed;
    if rest.starts_with('(') {
        rest = &rest[1..];
    }
    let digit_count = rest.chars().take_while(|ch| ch.is_ascii_digit()).count();
    if !(1..=4).contains(&digit_count) {
        return false;
    }
    rest = &rest[digit_count..];
    if rest.starts_with(')') {
        rest = &rest[1..];
    }
    rest.chars().next().is_some_and(char::is_whitespace)
}

fn lm2_context_feature_vector(
    decoded: &[(DeepLiquidSourceLine, Lm2Action)],
    baseline_actions: &[Lm2Action],
    block_meta: &HashMap<String, Lm2ContextBlockMeta>,
    index: usize,
) -> Vec<f64> {
    let line = &decoded[index].0;
    let shape = lm2_context_text_shape(&collapse_whitespace(&line.text));
    let block = block_meta.get(&line.id).cloned().unwrap_or_default();
    let width = (line.page_width as f64).max(1.0);
    let height = (line.page_height as f64).max(1.0);
    let mut features = Vec::with_capacity(66);
    lm2_context_onehot(&mut features, baseline_actions.get(index).copied());
    lm2_context_onehot(
        &mut features,
        index
            .checked_sub(1)
            .and_then(|idx| baseline_actions.get(idx))
            .copied(),
    );
    lm2_context_onehot(&mut features, baseline_actions.get(index + 1).copied());
    lm2_context_onehot(
        &mut features,
        index
            .checked_sub(2)
            .and_then(|idx| baseline_actions.get(idx))
            .copied(),
    );
    lm2_context_onehot(&mut features, baseline_actions.get(index + 2).copied());
    features.extend([
        line.left as f64 / width,
        line.right as f64 / width,
        line.top as f64 / height,
        line.bottom as f64 / height,
        line.font_height as f64,
        line.font_ratio_page as f64,
        line.font_ratio_doc as f64,
        line.doc_font_body_z as f64,
        line.doc_font_footnote_z as f64,
        bool_as_f64(line.bold),
        bool_as_f64(line.italic),
        bool_as_f64(line.centered),
        bool_as_f64(line.below_footnote_divider),
        bool_as_f64(line.in_footnote_zone),
        bool_as_f64(
            line.doc_repeated_top_edge
                || line.doc_repeated_bottom_edge
                || line.doc_repeated_edge_text,
        ),
        bool_as_f64(
            line.doc_vertical_axis_like
                || line.doc_vertical_numeric_axis_like
                || line.page_table_column_like,
        ),
        bool_as_f64(line.prev_line_has_dotleader || line.prev4_toc_leader_context),
        line.doc_note_marker as f64,
        bool_as_f64(line.doc_note_marker_first_on_page),
        bool_as_f64(line.doc_note_marker_mid_sequence_page),
        bool_as_f64(line.doc_note_marker_follows_previous_page),
        shape.char_count,
        shape.token_count,
        shape.short_text,
        shape.numeric_or_roman,
        shape.allcaps,
        shape.digit_ratio,
        shape.upper_ratio,
        shape.dotleader,
        shape.note_start,
        block.block_line_count.max(1) as f64,
        block.block_char_count as f64,
        block.block_short_ratio,
        block.block_numeric_ratio,
        block.block_dotleader,
        block.block_note_start_ratio,
        block.block_edge_ratio,
        block.block_axis_ratio,
        block.block_footzone_ratio,
        block.block_pos_norm,
        bool_as_f64(line.segment_block_first),
        bool_as_f64(line.segment_block_last),
        line.segment_block_line_count.max(1) as f64,
        line.segment_block_line_index as f64,
        bool_as_f64(line.segment_block_footnote_like),
        bool_as_f64(line.segment_block_furniture_like),
        bool_as_f64(line.segment_block_table_like),
        bool_as_f64(line.segment_block_toc_like),
    ]);
    lm2_context_onehot(
        &mut features,
        block
            .block_action
            .or_else(|| baseline_actions.get(index).copied()),
    );
    features
}

impl Lm2Model {
    fn doc_font_zscores_enabled(&self) -> bool {
        self.feature_schema
            .as_ref()
            .is_some_and(|schema| schema.doc_font_zscores)
    }

    fn repetition_fingerprints_enabled(&self) -> bool {
        self.feature_schema
            .as_ref()
            .is_some_and(|schema| schema.repetition_fingerprints)
    }

    fn marker_continuity_enabled(&self) -> bool {
        self.feature_schema
            .as_ref()
            .is_some_and(|schema| schema.marker_continuity)
    }
}

impl Lm2NativeCatboostModel {
    fn emission_scores(&self, line: &DeepLiquidSourceLine) -> Result<[f64; 3], String> {
        let feature_map = lm2_numeric_catboost_features(line);
        let float_features = LM2_NATIVE_CATBOOST_FLOAT_FEATURES
            .iter()
            .map(|name| feature_map.get(*name).copied().unwrap_or(0.0) as c_float)
            .collect::<Vec<_>>();
        let cat_values = lm2_native_catboost_cat_features(line);
        let cat_cstrings = cat_values
            .iter()
            .map(|value| {
                CString::new(value.as_str())
                    .map_err(|_| "NUL byte in categorical feature".to_owned())
            })
            .collect::<Result<Vec<_>, _>>()?;
        let text = collapse_whitespace(&line.text)
            .chars()
            .take(500)
            .collect::<String>();
        let text_cstring =
            CString::new(text).map_err(|_| "NUL byte in CatBoost text feature".to_owned())?;

        let float_rows = [float_features.as_ptr()];
        let cat_ptrs = cat_cstrings
            .iter()
            .map(|value| value.as_ptr())
            .collect::<Vec<_>>();
        let cat_rows = [cat_ptrs.as_ptr()];
        let text_ptrs = [text_cstring.as_ptr()];
        let text_rows = [text_ptrs.as_ptr()];
        let mut raw = vec![0.0; self.dimensions_count];
        let ok = unsafe {
            (self.calc_model_prediction_text)(
                self.handle,
                1,
                float_rows.as_ptr(),
                float_features.len(),
                cat_rows.as_ptr(),
                cat_ptrs.len(),
                text_rows.as_ptr(),
                text_ptrs.len(),
                raw.as_mut_ptr(),
                raw.len(),
            )
        };
        if !ok {
            return Err(self.last_error());
        }
        if raw.len() != 3 {
            return Err(format!("native CatBoost returned {} dimensions", raw.len()));
        }
        // This promoted CBM reports classes in CatBoost/Python order:
        // ["hide_noise", "keep", "marginalia"].
        Ok([
            raw[1], // keep
            raw[2], // marginalia
            raw[0], // hide_noise
        ])
    }

    fn last_error(&self) -> String {
        let ptr = unsafe { (self.get_error_string)() };
        if ptr.is_null() {
            return "CatBoost C API error".to_owned();
        }
        unsafe { CStr::from_ptr(ptr) }
            .to_string_lossy()
            .into_owned()
    }
}

impl Drop for Lm2NativeCatboostModel {
    fn drop(&mut self) {
        if !self.handle.is_null() {
            unsafe {
                (self.delete_model)(self.handle);
            }
            self.handle = std::ptr::null_mut();
        }
    }
}

impl Lm2NumericCatboostModel {
    fn is_usable(&self) -> bool {
        self.schema_version == "lm2-numeric-catboost-runtime-v1"
            && self.model_type == "numeric_catboost_oblivious_trees_v1"
            && self.classes.len() == ACTIONS.len()
            && self.bias.len() == self.classes.len()
            && !self.features.is_empty()
            && !self.trees.is_empty()
            && self.trees.iter().all(|tree| {
                let leaf_count = 1usize << tree.splits.len();
                tree.leaf_values.len() == leaf_count * self.classes.len()
                    && tree
                        .splits
                        .iter()
                        .all(|split| split.feature_index < self.features.len())
            })
    }

    fn emission_scores(&self, line: &DeepLiquidSourceLine) -> [f64; 3] {
        let features = lm2_numeric_catboost_features(line);
        let mut class_scores = self.bias.clone();
        class_scores.resize(self.classes.len(), 0.0);
        for tree in &self.trees {
            let mut leaf = 0usize;
            for (depth, split) in tree.splits.iter().enumerate() {
                let feature_name = &self.features[split.feature_index].name;
                let value = features.get(feature_name.as_str()).copied().unwrap_or(0.0);
                if value > split.border {
                    leaf |= 1usize << depth;
                }
            }
            let offset = leaf * self.classes.len();
            for (class_index, score) in class_scores.iter_mut().enumerate() {
                *score += self.scale * tree.leaf_values[offset + class_index];
            }
        }
        let mut action_scores = [0.0, 0.0, 0.0];
        for (class_index, class_name) in self.classes.iter().enumerate() {
            let action_index = match class_name.as_str() {
                "keep" => Lm2Action::Keep.index(),
                "marginalia" => Lm2Action::Marginalia.index(),
                "hide_noise" => Lm2Action::HideNoise.index(),
                _ => continue,
            };
            action_scores[action_index] = class_scores[class_index];
        }
        action_scores
    }
}

fn model_is_usable(model: &Lm2Model) -> bool {
    model.model_type == "hashed_softmax_action_v1"
        && model.actions == ACTIONS.map(|action| action.as_str().to_owned())
        && model.feature_dim > 0
        && model.bias.len() == ACTIONS.len()
        && model.weights.len() == ACTIONS.len()
        && model
            .weights
            .iter()
            .all(|weights| weights.len() == model.feature_dim)
}

fn load_lm2_model() -> Result<Lm2Model, String> {
    let candidates = lm2_model_candidates();
    let path = candidates
        .iter()
        .find(|path| path.is_file())
        .cloned()
        .ok_or_else(|| missing_model_error("legacy LM2 model", &candidates))?;
    let bytes =
        std::fs::read(&path).map_err(|error| format!("Could not read LM2 model: {error}"))?;
    serde_json::from_slice(&bytes).map_err(|error| format!("Could not decode LM2 model: {error}"))
}

fn load_lm2_native_catboost_model() -> Result<Option<Lm2NativeCatboostModel>, String> {
    let mut model_candidates = Vec::new();
    if let Some(path) = std::env::var_os("LAWPDF_LM2_NATIVE_CATBOOST_MODEL").map(PathBuf::from) {
        model_candidates.push(path);
    }
    model_candidates.extend(lm2_native_catboost_runtime_asset_candidates(
        LM2_NATIVE_CATBOOST_MODEL_FILE,
    ));
    let model_path = model_candidates
        .iter()
        .find(|path| path.is_file())
        .cloned()
        .ok_or_else(|| missing_model_error("LM2 native CatBoost model", &model_candidates))?;
    verify_model_asset_hash(&model_path, "native_model")?;
    let model_sha256 = sha256_hex_of_file(&model_path)?;

    let mut library_candidates = Vec::new();
    if let Some(path) = std::env::var_os("LAWPDF_LM2_NATIVE_CATBOOST_LIB").map(PathBuf::from) {
        library_candidates.push(path);
    }
    library_candidates.extend(lm2_native_catboost_runtime_asset_candidates(
        lm2_native_catboost_library_file(),
    ));
    let lib_path = library_candidates
        .iter()
        .find(|path| path.is_file())
        .cloned()
        .ok_or_else(|| missing_model_error("LM2 native CatBoost library", &library_candidates))?;
    let library = unsafe { Library::new(&lib_path) }
        .map_err(|error| format!("Could not load native CatBoost library: {error}"))?;
    let (
        create_model,
        delete_model,
        load_full_model_from_file,
        get_float_features_count,
        get_cat_features_count,
        get_text_features_count,
        get_dimensions_count,
        get_error_string,
        calc_model_prediction_text,
    ) = unsafe {
        (
            *library
                .get::<CatboostCreateFn>(b"ModelCalcerCreate\0")
                .map_err(|error| format!("CatBoost library missing ModelCalcerCreate: {error}"))?,
            *library
                .get::<CatboostDeleteFn>(b"ModelCalcerDelete\0")
                .map_err(|error| format!("CatBoost library missing ModelCalcerDelete: {error}"))?,
            *library
                .get::<CatboostLoadFullModelFromFileFn>(b"LoadFullModelFromFile\0")
                .map_err(|error| {
                    format!("CatBoost library missing LoadFullModelFromFile: {error}")
                })?,
            *library
                .get::<CatboostGetCountFn>(b"GetFloatFeaturesCount\0")
                .map_err(|error| {
                    format!("CatBoost library missing GetFloatFeaturesCount: {error}")
                })?,
            *library
                .get::<CatboostGetCountFn>(b"GetCatFeaturesCount\0")
                .map_err(|error| {
                    format!("CatBoost library missing GetCatFeaturesCount: {error}")
                })?,
            *library
                .get::<CatboostGetCountFn>(b"GetTextFeaturesCount\0")
                .map_err(|error| {
                    format!("CatBoost library missing GetTextFeaturesCount: {error}")
                })?,
            *library
                .get::<CatboostGetCountFn>(b"GetDimensionsCount\0")
                .map_err(|error| format!("CatBoost library missing GetDimensionsCount: {error}"))?,
            *library
                .get::<CatboostGetErrorStringFn>(b"GetErrorString\0")
                .map_err(|error| format!("CatBoost library missing GetErrorString: {error}"))?,
            *library
                .get::<CatboostCalcModelPredictionTextFn>(b"CalcModelPredictionText\0")
                .map_err(|error| {
                    format!("CatBoost library missing CalcModelPredictionText: {error}")
                })?,
        )
    };

    let handle = unsafe { create_model() };
    if handle.is_null() {
        return Err("Could not create CatBoost model handle".to_owned());
    }
    let model_path_string = model_path.to_string_lossy().into_owned();
    let model_path_c = CString::new(model_path_string)
        .map_err(|_| "NUL byte in LAWPDF_LM2_NATIVE_CATBOOST_MODEL".to_owned())?;
    let loaded = unsafe { load_full_model_from_file(handle, model_path_c.as_ptr()) };
    if !loaded {
        let error = catboost_error_string(get_error_string);
        unsafe {
            delete_model(handle);
        }
        return Err(format!(
            "Could not load native CatBoost model {}: {error}",
            model_path.display()
        ));
    }
    let float_feature_count = unsafe { get_float_features_count(handle) };
    let cat_feature_count = unsafe { get_cat_features_count(handle) };
    let text_feature_count = unsafe { get_text_features_count(handle) };
    let dimensions_count = unsafe { get_dimensions_count(handle) };
    if float_feature_count != LM2_NATIVE_CATBOOST_FLOAT_FEATURES.len()
        || cat_feature_count != LM2_NATIVE_CATBOOST_CAT_FEATURES.len()
        || text_feature_count != 1
        || dimensions_count != 3
    {
        unsafe {
            delete_model(handle);
        }
        return Err(format!(
            "Native CatBoost feature contract mismatch: got f{float_feature_count}/c{cat_feature_count}/t{text_feature_count}/d{dimensions_count}, expected f{}/c{}/t1/d3",
            LM2_NATIVE_CATBOOST_FLOAT_FEATURES.len(),
            LM2_NATIVE_CATBOOST_CAT_FEATURES.len()
        ));
    }
    Ok(Some(Lm2NativeCatboostModel {
        _library: library,
        handle,
        delete_model,
        calc_model_prediction_text,
        get_error_string,
        float_feature_count,
        cat_feature_count,
        text_feature_count,
        dimensions_count,
        model_sha256,
    }))
}

fn catboost_error_string(get_error_string: CatboostGetErrorStringFn) -> String {
    let ptr = unsafe { get_error_string() };
    if ptr.is_null() {
        return "CatBoost C API error".to_owned();
    }
    unsafe { CStr::from_ptr(ptr) }
        .to_string_lossy()
        .into_owned()
}

fn load_lm2_numeric_catboost_model() -> Result<Option<Lm2NumericCatboostModel>, String> {
    let path = std::env::var_os("LAWPDF_LM2_NUMERIC_CATBOOST_MODEL")
        .map(PathBuf::from)
        .or_else(|| {
            lm2_v20_stack_runtime_enabled()
                .then(|| lm2_v20_runtime_asset_candidates("lm2-numeric-catboost-runtime.json"))
                .and_then(|candidates| candidates.into_iter().find(|path| path.is_file()))
        });
    let Some(path) = path else { return Ok(None) };
    let bytes = std::fs::read(&path)
        .map_err(|error| format!("Could not read LM2 numeric CatBoost model: {error}"))?;
    let model = serde_json::from_slice::<Lm2NumericCatboostModel>(&bytes)
        .map_err(|error| format!("Could not decode LM2 numeric CatBoost model: {error}"))?;
    if !model.is_usable() {
        return Err("LM2 numeric CatBoost model is not usable".to_owned());
    }
    Ok(Some(model))
}

fn load_lm2_static_front_overlay() -> Result<Option<Lm2StaticFrontOverlay>, String> {
    let a55_path = std::env::var_os("LAWPDF_LM2_A55_OVERLAY")
        .map(PathBuf::from)
        .or_else(|| {
            lm2_v20_stack_runtime_enabled()
                .then(|| lm2_v20_runtime_asset_candidates("a55-front-stack-overlay.jsonl"))
                .and_then(|candidates| candidates.into_iter().find(|path| path.is_file()))
        });
    let d3_path = std::env::var_os("LAWPDF_LM2_D3_OVERLAY")
        .map(PathBuf::from)
        .or_else(|| {
            lm2_v20_stack_runtime_enabled()
                .then(|| lm2_v20_runtime_asset_candidates("d3-front-matter-regions.jsonl"))
                .and_then(|candidates| candidates.into_iter().find(|path| path.is_file()))
        });
    if a55_path.is_none() && d3_path.is_none() {
        return Ok(None);
    }

    let mut roles_by_doc_line: HashMap<String, HashMap<String, LiquidBlockRole>> = HashMap::new();
    let mut labels = Vec::new();
    if let Some(path) = a55_path {
        load_lm2_a55_overlay_rows(&path, &mut roles_by_doc_line)?;
        labels.push(format!("a55:{:016x}", fnv1a64(&path.display().to_string())));
    }
    if let Some(path) = d3_path {
        load_lm2_d3_overlay_rows(&path, &mut roles_by_doc_line)?;
        labels.push(format!("d3:{:016x}", fnv1a64(&path.display().to_string())));
    }
    if roles_by_doc_line.is_empty() {
        return Ok(None);
    }
    Ok(Some(Lm2StaticFrontOverlay {
        source_label: labels.join("+"),
        roles_by_doc_line,
    }))
}

fn load_lm2_a55_overlay_rows(
    path: &Path,
    roles_by_doc_line: &mut HashMap<String, HashMap<String, LiquidBlockRole>>,
) -> Result<(), String> {
    let text = std::fs::read_to_string(path)
        .map_err(|error| format!("Could not read LM2 A55 overlay rows: {error}"))?;
    for (line_number, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let row = serde_json::from_str::<serde_json::Value>(line).map_err(|error| {
            format!(
                "Could not decode LM2 A55 overlay row {} in {}: {error}",
                line_number + 1,
                path.display()
            )
        })?;
        let doc = normalize_path_key_value(row.get("doc_path"));
        let line_id = row
            .get("line_id")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_owned();
        let role = row
            .get("to_role")
            .and_then(|value| value.as_str())
            .and_then(role_from_name);
        if doc.is_empty() || line_id.is_empty() {
            continue;
        }
        if let Some(role) = role {
            roles_by_doc_line
                .entry(doc)
                .or_default()
                .insert(line_id, role);
        }
    }
    Ok(())
}

fn load_lm2_d3_overlay_rows(
    path: &Path,
    roles_by_doc_line: &mut HashMap<String, HashMap<String, LiquidBlockRole>>,
) -> Result<(), String> {
    let text = std::fs::read_to_string(path)
        .map_err(|error| format!("Could not read LM2 D3 overlay rows: {error}"))?;
    for (line_number, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let row = serde_json::from_str::<serde_json::Value>(line).map_err(|error| {
            format!(
                "Could not decode LM2 D3 overlay row {} in {}: {error}",
                line_number + 1,
                path.display()
            )
        })?;
        let doc = normalize_path_key_value(row.get("source_path"));
        let line_id = row
            .get("line_id")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_owned();
        let role = match row
            .get("front_matter_kind")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
        {
            "title" => Some(LiquidBlockRole::Title),
            "section_heading" => Some(LiquidBlockRole::Heading),
            "author" | "abstract" => Some(LiquidBlockRole::Marginalia),
            _ => None,
        };
        if doc.is_empty() || line_id.is_empty() {
            continue;
        }
        if let Some(role) = role {
            roles_by_doc_line
                .entry(doc)
                .or_default()
                .insert(line_id, role);
        }
    }
    Ok(())
}

fn normalize_path_key_value(value: Option<&serde_json::Value>) -> String {
    value
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .replace('\\', "/")
        .to_lowercase()
}

fn load_lm2_pp_priors() -> Result<Option<Lm2PpPriorIndex>, String> {
    let Some(path) = std::env::var_os("LAWPDF_LM2_PP_DRAFTS").map(PathBuf::from) else {
        return Ok(None);
    };
    load_lm2_pp_priors_from_path(path)
}

fn load_lm2_pp_priors_from_path(path: PathBuf) -> Result<Option<Lm2PpPriorIndex>, String> {
    let text = std::fs::read_to_string(&path)
        .map_err(|error| format!("Could not read LM2 PP draft rows: {error}"))?;
    let mut rows = HashMap::new();
    for (line_number, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let row: Lm2PpDraftRow = serde_json::from_str(line).map_err(|error| {
            format!(
                "Could not decode LM2 PP draft row {} in {}: {error}",
                line_number + 1,
                path.display()
            )
        })?;
        let action = row.draft_action.as_deref().or(row.pp_action.as_deref());
        let role = row.pp_role.unwrap_or_default();
        let label = row.pp_label.unwrap_or_default();
        let score = row.pp_score.unwrap_or_default();
        if !guarded_pp_prior_action(action, &role, &label, score, &row.text) {
            continue;
        }
        let source_path = if row.source_path.is_empty() {
            row.path
        } else {
            row.source_path
        };
        if source_path.is_empty() {
            continue;
        }
        rows.insert(
            pp_prior_key(&source_path, row.page_index, row.line_index, &row.text),
            Lm2PpPrior { role, label, score },
        );
    }
    if rows.is_empty() {
        return Ok(None);
    }
    Ok(Some(Lm2PpPriorIndex { source: path, rows }))
}

fn load_or_generate_lm2_pp_priors(
    path: &Path,
    source_lines: &[DeepLiquidSourceLine],
) -> Result<Option<Lm2PpPriorIndex>, String> {
    if source_lines.is_empty() {
        return Ok(None);
    }
    let cache_key = lm2_pp_doclayout_cache_key(path, source_lines);
    let draft_path = lm2_pp_doclayout_draft_cache_path(&cache_key)
        .ok_or_else(|| "could not find LM2 PP-DocLayout cache directory".to_owned())?;
    if draft_path.is_file() {
        return load_lm2_pp_priors_from_path(draft_path);
    }
    run_lm2_pp_doclayout_sidecar(path, source_lines, &cache_key, &draft_path)?;
    if draft_path.is_file() {
        return load_lm2_pp_priors_from_path(draft_path);
    }
    Ok(None)
}

fn lm2_pp_prior_index_has_footnotes(index: &Lm2PpPriorIndex) -> bool {
    index
        .rows
        .values()
        .any(|prior| prior.role == "footnote" && prior.score >= 0.80)
}

fn guarded_pp_prior_action(
    action: Option<&str>,
    role: &str,
    label: &str,
    score: f64,
    text: &str,
) -> bool {
    let compact_text = text.split_whitespace().collect::<String>();
    role == "footnote"
        && action == Some("marginalia")
        && score >= 0.80
        && !compact_text.chars().all(|ch| ch.is_ascii_digit())
        || role == "table" && action == Some("hide_noise") && score >= 0.70
        || label == "number" && action == Some("hide_noise") && score >= 0.80
}

