    #[test]
    fn guarded_pp_prior_rejects_numeric_footnote_rows() {
        assert!(guarded_pp_prior_action(
            Some("marginalia"),
            "footnote",
            "footnote",
            0.80,
            "Some real note text"
        ));
        assert!(!guarded_pp_prior_action(
            Some("marginalia"),
            "footnote",
            "footnote",
            0.799,
            "Some real note text"
        ));
        assert!(guarded_pp_prior_action(
            Some("marginalia"),
            "footnote",
            "footnote",
            0.90,
            "Some real note text"
        ));
        assert!(!guarded_pp_prior_action(
            Some("marginalia"),
            "footnote",
            "footnote",
            0.90,
            "775"
        ));
        assert!(guarded_pp_prior_action(
            Some("hide_noise"),
            "table",
            "table",
            0.75,
            "table row"
        ));
    }

